INSERT INTO "states" ("id", "name", "code", "region", "capital", "description", "history", "culture", "rituals", "handicrafts", "food", "festivals", "iconic_battles", "image_url", "cultural_identity", "historical_overview", "arts_and_crafts", "festivals_and_rituals", "cuisine_and_languages", "important_personalities", "source_name", "source_url", "source_type", "last_verified_at") VALUES
  (1, 'Andaman and Nicobar Islands', 'AN', 'Islands', 'Port Blair', 'A chain of 572 islands known for pristine beaches, indigenous communities and the Cellular Jail, a symbol of India''s freedom struggle.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'A union territory of indigenous tribal heritage, colonial freedom-struggle memorials, and marine biodiversity — where the Sentinelese, Onge and Great Andamanese guard one of the oldest continuous cultures on earth.', 'Inhabited for over 60,000 years by negrito tribes, the islands passed through Mughal, Danish, British and Japanese control. The Cellular Jail (1906–1942) became the most feared prison of the Indian freedom struggle, housing political prisoners like Vinayak Damodar Savarkar. Post-Independence, the islands were reorganised as a union territory in 1956.', 'Nicobari canoe-making (the Mumu), Shompen bamboo craft, and shell-based jewellery by the indigenous communities.', 'Island Tourism Festival (January), Mini Mahotsav, Tarpa dance of the Onge, and the Lighthouse Festival at Port Blair.', 'Bengali, Tamil, Hindi and Malayalam are widely spoken. Coconut-based seafood curries, fish tikka and tropical fruit desserts dominate the local cuisine.', 'Vinayak Damodar Savarkar (political prisoner), Captain Raju (freedom fighter), Prof. D.P. Chattopadhyaya (anthropologist).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (2, 'Andhra Pradesh', 'AP', 'South', 'Amaravati', 'Land of the Kuchipudi dance form, Tirupati temple town and a rich coastline of craft and classical music.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The land of Kuchipudi, Tirupati, and the ancient Satavahana and Vijayanagara legacies — a state where temple towns, classical dance and coastal craft traditions converge.', 'From the Satavahanas (2nd c. BCE) through the Ikshvakus, Pallavas, Eastern Chalukyas, Kakatiyas and the Vijayanagara empire, Andhra has been a continuous seat of Dravidian civilisation. The Qutb Shahi and Nizam courts shaped Hyderabad''s composite culture before the 1956 linguistic reorganisation.', 'Kalamkari (Srikalahasti and Machilipatnam styles), Kondapalli toys, Etikoppaka lacquerware, Gadhwal and Venkatagiri sarees, and Pochampally ikat weaving.', 'Tirumala Brahmotsavam, Sankranti (Pedda Panduga), Ugadi, Lamma Bada, and the Kalamkari craft festival at Machilipatnam.', 'Telugu is the principal language. Coastal Andhra cuisine features pesarattu, gongura, and spicy seafood; Rayalaseema favours fiery curries. Hyderabadi biryani and haleem are iconic.', 'N.T. Rama Rao (actor-politician), M. Tyagaraja (Carnatic composer, associated with Tiruvaiyaru), Sarvepalli Radhakrishnan (philosopher-president, born in Tiruttani).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (3, 'Arunachal Pradesh', 'AR', 'Northeast', 'Itanagar', 'A mountainous state of tribal cultures, monasteries and the sacred Tawang region.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The Land of Dawn-lit Mountains — a mosaic of 26 major tribal groups, each with distinct languages, animist-Buddhist faiths and the famed Tawang Monastery tradition.', 'Part of the Monyul kingdom and later the Tawang tract under Tibetan influence, Arunachal was administered as the North-East Frontier Agency (NEFA) until 1972. It became a full state in 1987. The Tawang Monastery (1680) is the largest Buddhist monastery in India.', 'Apatani cane and bamboo work, Monpa thangka painting, Nocte tribal woodcarving, and shawl weaving of the Wancho and Tirap communities.', 'Tawang Monastery festival (Losar), Ziro Music Festival, Torgya dance at Tawang, Myoko festival of the Apatani, and the second-day Solung of the Adi tribe.', 'Tibeto-Burman languages (Monpa, Adi, Apatani, Nocte, Wancho) alongside Hindi and Assamese. Rice-based diet with bamboo shoot pickle (mesu), boiled meat and fermented soya (axone).', 'Tsetan Dorjei Naksang (Tawang spiritual leader), Lummer Dai (Assamese writer of Arunachal origin).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (4, 'Assam', 'AS', 'Northeast', 'Dispur', 'Known for the one-horned rhinoceros, Bihu festival, satras and world-famous Assam silk and tea culture.', 'The fertile Brahmaputra valley nurtured the kingdoms of Pragjyotisha-Kamrupa, later the Ahom empire (13th-19th c.) which repelled repeated Mughal invasions.', 'Bihu dance, borgeet devotional music of the satras, Sattriya classical dance, jhumur folk songs and the annual Kesodhya literary assemblies.', 'The three Bihus (Rongali, Kongali, Bhogali) and the annual satra (seat) rituals of Vaishnavism.', 'Muga, Eri and Pat silks, cane and bamboo craft, and the ''xapkalai'' terracotta of Kopili basin.', 'Masor tenga (sour fish), pitha, khulli bhaat with chutney and pungent ''jorhat'' tea culture.', 'Bihu|Ambubachi Mela|Brahmaputra Beach Festival|Maji Mela|Kaziranga elephant festival', 'The Battle of Saraighat (1671) — the Ahom naval victory against the Mughals.', '', 'The gateway to the Northeast — a state of Bihu dances, Vaishnavite satras, Muga silk, one-horned rhinoceros and the Ahom legacy that repelled Mughal invasions for centuries.', 'The ancient kingdom of Pragjyotisha-Kamrupa gave way to the Ahom dynasty (1228–1826), which ruled for 600 years and created a unique synthesis of Tai and Assamese culture. The British annexation (1826) and the 1947 Partition shaped modern Assam''s tea and oil economy.', 'Muga, Eri and Pat silks, bell-metal (kanh) craft, bamboo and cane weaving, and the traditional Assamese mask-making of Majuli''s Sattras.', 'Rongali Bihu (spring), Magh Bihu, Ambubachi Mela at Kamakhya, Bihu dance, Sattriya dance, and the Kaziranga elephant festival.', 'Assamese (Indo-Aryan) and Bodo languages. Khar (alkaline dishes), masor tenga (sour fish), pitha, and the betel-leaf culture of Bihu gatherings.', 'Srimanta Sankardeva (Vaishnavite saint-reformer), Lachit Borphukan (Ahom general of Saraighat), Bhupen Hazarika (musician).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (5, 'Bihar', 'BR', 'East', 'Patna', 'Cradle of ancient empires — Magadha, Maurya and Gupta — and the site of Bodh Gaya.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The cradle of Buddhism and Jainism, seat of the Maurya and Gupta empires — where the world''s oldest university (Nalanda) once drew scholars from across Asia.', 'Bihar was the heartland of the Magadha mahajanapada, the Maurya empire (Ashoka), the Gupta golden age, and the Buddhist and Jain monastic traditions. Nalanda and Vikramashila were among the world''s earliest residential universities. The 1857 revolt, Champaran satyagraha (1917) and the Quit India movement at the Buddha Smriti Park mark its modern chapters.', 'Madhubani (Mithila) painting, Sujni embroidery, Sikki grass craft, and the terracotta and stone sculpture of ancient Pataliputra.', 'Chhath Puja (dedicated to the Sun God), Sonepur cattle fair, Shravani Mela at Deoghar, and the Buddha Purnima celebrations at Bodh Gaya.', 'Hindi, Bhojpuri, Maithili and Magahi. Litti-chokha, sattu paratha, thekua and the maize-based cuisine of the Bhojpur region.', 'Dr. Rajendra Prasad (first President), Jayaprakash Narayan (freedom fighter), Vidyapati (Maithili poet), Chandragupta Maurya.', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (6, 'Chandigarh', 'CH', 'North', 'Chandigarh', 'India''s modernist capital city, designed by Le Corbusier, and its own Union Territory.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'India''s first planned city — a living experiment in modernist urbanism by Le Corbusier, blending open gardens, geometric order and the Rock Garden''s folk-art rebellion.', 'Carved out of Punjab after Partition (1966), Chandigarh was designed by Le Corbusier as the capital of Punjab and Haryana. The Capitol Complex, Open Hand Monument and Rock Garden by Nek Chand represent a unique fusion of high modernism and grassroots creativity.', 'Nek Chand''s Rock Garden (recycled material sculpture), Le Corbusier''s Open Hand, and the contemporary art scene of Sector 17.', 'Chandigarh Carnival, Rose Festival at the Rose Garden, and the international kite festival.', 'Punjabi and Hindi. North Indian cuisine — chole bhature, paranthas, and the Sector 26 food street.', 'Le Corbusier (architect), Nek Chand (Rock Garden creator), M.S. Randhawa (first chief commissioner).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (7, 'Chhattisgarh', 'CG', 'Central', 'Raipur', 'A state of tribal heritage, the Bastar Dussehra and the ancient rock art of Chitradurg.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The rice bowl of India — a state of tribal Dussehra, Bastar''s living folk traditions, and ancient rock-art sites in the Maikal hills.', 'Part of the Dakshina Kosala kingdom and later the Maratha and British-administered Central Provinces, Chhattisgarh was carved out of Madhya Pradesh in 2000. The Bastar region preserves some of the oldest tribal governance systems and art traditions in India.', 'Bastar iron craft (Dhokra lost-wax), Terracotta of Chirmi, Kosa silk weaving, and the Geria and Patari tribal art forms.', 'Bastar Dussehra (a 75-day tribal festival unique in India), Madai festival, and the PRIKAMA tribal fair.', 'Chhattisgarhi (Hindi-like), Halbi, Gondi and Bastari. Mahua-based beverages, bafauri (chickpea flour dumplings), and red-ant chutney of Bastar.', 'Pt. Sundarlal Sharma (freedom fighter), Genda Karma (folk dancer).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (8, 'Dadra and Nagar Haveli and Daman and Diu', 'DN', 'West', 'Daman', 'Coastal territories with fortified colonial-era structures and tribal Warlis art.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'A coastal union territory of Warli tribal art, Portuguese colonial relics and the Silvassa-Daman-Diu triangle of cross-cultural coexistence.', 'Portuguese colonies since the 16th century, Dadra and Nagar Haveli were liberated in 1954 and Daman and Diu in 1961. Merged into a single union territory in 2020, the region preserves Indo-Portuguese architecture, Warli murals and tribal governance systems.', 'Warli wall painting (geometric motifs on mud walls), bamboo craft, and the Portuguese-influenced tile-work of Daman.', 'VAutha Fair (Daman), Tarpa dance festival of the Warlis, and the Diu Fort festival.', 'Gujarati, Hindi, Konkani and Portuguese-influenced cuisine. Seafood, bebinca (Goan-Portuguese dessert) and the local Kaju feni.', 'Vasudev Gopal Krishna Gaitonde (abstract painter, raised in Daman).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (9, 'Delhi', 'DL', 'North', 'New Delhi', 'Seven cities of history in one — Delhi is a living museum spanning 13 centuries of rule.', 'From the Tomar Chauhans and the Sultans of Delhi through Mughal and British capitals to the seat of the Republic — Delhi concentrates the nation''s imperial loops.', 'The qawwali and mehfil culture, Daryaganj''s book bazaars, the crafts of Matia Mahal and the institutional museum belt of the national capital.', 'The Republic and Independence day parades; the autumnal Diva nights and Chandni Chowk halvai evenings.', 'Village-haat arts, extension of Chikankari into Delhi''s ateliers, and the hand-block prints of the national crafts melas.', 'Chhole-bhature, Chaat of Paranthe Wali Gali, galouti kebabs of old Delhi and the Irani cafe sweets.', 'International Kite Festival|Garden of Five Senses festivals|Jahan-e-Khusrau|Republic Day Beating Retreat|National Crafts Fair', 'The battles of Tarain (1191-92) and Panipat; the Siege of Delhi 1857.', '', 'Seven cities of empires compressed into one metropolis — from the Qutb Minar to the Red Fort, Delhi is the political and cultural nerve-centre of the Republic.', 'From the Tomar fort of Lal Kot (8th c.) through the Delhi Sultanate (1206–1526), the Mughal Empire (1526–1857) and British colonial New Delhi (1911–1947), the city has been rebuilt at least seven times. The 1857 siege, the 1947 Partition, and the modern Republic make Delhi a palimpsest of power.', 'Chikankari embroidery (Delhi ateliers), Dilli Haat crafts bazaar, Zardozi gold-work, and the silver filigree of Chandni Chowk.', 'Republic Day parade (Kartavya Path), Independence Day at Red Fort, Qutb Festival of Indian music, and the International Kite Festival.', 'Hindi and Urdu. Paranthe Wali Gali, Old Delhi kebabs and nihari, Karim''s Mughlai, and the Irani cafe culture of Connaught Place.', 'Shah Jahan (built Shahjahanabad), Mahatma Gandhi (shot at Birla House), Dr. B.R. Ambedkar (drafted Constitution in Delhi).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (10, 'Goa', 'GA', 'West', 'Panaji', 'A coastal state of Indo-Portuguese heritage, churches, temples, and Carnival festivities.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'India''s smallest state — a four-hundred-year-old Portuguese Catholic cultural layer over ancient Hindu temples, Konkani music and tropical coastal life.', 'Portuguese rule (1510–1961) left a unique Indo-Latin heritage — churches of Old Goa, the Basilica of Bom Jesus (1605), and the Latin Quarter of Fontainhas. Pre-colonial Goa was a centre of the Kadamba and Vijayanagara dynasties and a spice-trade hub.', 'Azulejo tile painting, brass lamp and bell-metal craft, Kokani textile weaving, and the Konkani tiatr theatre tradition.', 'Carnival (February), Sao Joao (June), Feast of St. Francis Xavier, Shigmo (Holi) and the Goa Cultural Festival.', 'Konkani (Devanagari and Roman scripts), Portuguese-legacy Catholic cuisine — vindaloo, xacuti, bebinca, and feni (cashew spirit).', 'St. Francis Xavier (relics at Old Goa), Mario Miranda (cartoonist), Lata Mangeshkar (born in Mangeshi, Goa).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (11, 'Gujarat', 'GJ', 'West', 'Gandhinagar', 'Land of Harappan ruins at Dholavira, colourful Navratri, handicrafts and the Rann of Kutch.', 'The Harappans at Dholavira, the western Kshatrapa empires, Gujarat''s medieval merchant republics, the 1857 uprising, and Mahatma Gandhi''s Sabarmati years.', 'Garba and raas-dandiya, Vāch-Raas of folk theatre, crafts of the desert and the world of Indian textiles.', 'Nine nights of Navratri garba, the Tarnetar fair, and devotion of the Narsinh Mehta bhajans.', 'Kutch embroidery, Bandhani tie-dye, Ajrakh block printing, Rogan art of Nirona and silver filigree of Haldasar.', 'Dhokla, Thepla, Undhiyu, Fafda-Jalebi and the swaying Bhavnagar ice-cream trade.', 'Navratri Garba|Rann Utsav|Surajkund-like International Kite Festival|Tarnetar Fair|Bhadra? fair of Kutch', 'The medieval coastal wars of the Chaulukyas and the Portuguese confrontation at Diu (1509).', '', 'The land of Mahatma Gandhi, Harappan Dholavira, nine nights of Navratri garba and the Rann''s white desert — a state of enterprise, craft and devotion.', 'Gujarat''s coast hosted the Harappan port of Lothal and Dholavira (2600 BCE). The Solanki (Chalukya) and Vaghela dynasties built the Modhera Sun Temple and the Rani ki Vav stepwell. Mahatma Gandhi''s Sabarmati Ashram became the nerve-centre of the freedom movement. The state was formed in 1960 from the bilingual Bombay state.', 'Kutch embroidery (Rabari, Ahir), Ajrakh block printing, Bandhani tie-dye, Rogan art of Nirona, Patola silk of Patan, and the silver filigree of Haldasar.', 'Navratri garba (nine nights across the state), Rann Utsav, International Kite Festival (Uttarayan), Tarnetar fair, and the Bhadra fair of Kutch.', 'Gujarati (sweet-savoury balance), Kutchi. Dhokla, thepla, fafda-jalebi, undhiyu, and the kathiyawadi cuisine of Saurashtra.', 'Mahatma Gandhi (Sabarmati Ashram), Sardar Vallabhbhai Patel (Statue of Unity), Narsinh Mehta (bhakti poet).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (12, 'Haryana', 'HR', 'North', 'Chandigarh', 'Home to the Mahabharata battlefield of Kurukshetra and a strong rural sporting culture.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The land of the Mahabharata''s Kurukshetra, the wrestling akharas and the pastoral Jat culture that straddles ancient mythology and modern sport.', 'The Kurukshetra plain is the mythical battlefield of the Mahabharata. Haryana was part of the Delhi Sultanate and Mughal Empire, later the Punjab province, and became a separate state in 1966. The Bhakra-Nangal dam and Green Revolution transformed its modern economy.', 'Phulkari embroidery,Durrie weaving, the brass and copper craft of Panipat, and the traditional pottery of Hisar.', 'Kurukshetra''s Solar Eclipse bathing festival, Pinjore Heritage Festival, Baisakhi, and the Haryana Surajkund Craft Mela.', 'Haryanvi (Hindi-like), Punjabi. Bajra khichdi, malpua, singri ki sabzi and the lassi culture of rural Haryana.', 'Baba Saheb Ambedkar (born in Mhow but Haryana claims strong Dalit-Buddhist links), Capt. Vikram Batra (Kargil hero, from Himachal but Haryana''s military legacy).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (13, 'Himachal Pradesh', 'HP', 'North', 'Shimla', 'A Himalayan state of wooden temples, handicrafts and the Kullu Dussehra festival.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'Dev Bhumi — the land of wooden temples, apple orchards, shawl-weaving valleys and the ancient Buddhist monasteries of the trans-Himalayan belt.', 'The hill kingdoms of Kullu, Chamba, Mandi and Bushahr flourished as princely states under Mughal suzerainty and later British paramountcy. Himachal became a state in 1971. The region''s wood-carved temples (Bhimakali, Hadimba) and monasteries (Key, Tabo, Rewalsar) are among India''s finest.', 'Kullu shawl weaving, Chamba rumal embroidery, Kangra miniature painting, and the wood-carved temples of the Sirmaur style.', 'Kullu Dussehra (international), Minjar fair of Chamba, Halda festival of Lahaul, and the Losar Buddhist new year in Spiti.', 'Himachali (Pahari dialects), Hindi. Dham feast, siddu (steamed bread), madra (chickpea curry) and the trout cuisine of Kullu.', 'Baba Bhag Singh (freedom fighter), Prem Prakash (cinematographer, born in Shimla).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (14, 'Jammu and Kashmir', 'JK', 'North', 'Srinagar (summer)', 'Known for Dal Lake, Mughal gardens, shawl handicrafts, and the legendary Kathak-Sufiyana traditions.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'Paradise on earth — Mughal gardens, Sufi-Kathak traditions, Pashmina shawl weaving and the syncretic Rishi-Sufi spiritual heritage of the Kashmir Valley.', 'The Kashmir Valley has been a centre of Shaivite philosophy (Abhinavagupta), Sanskrit learning and Persian-influenced court culture. The Mughal gardens (Nishat, Shalimar), the Pathan and Sikh rule, and the Dogra maharajas of Jammu shaped its layered history. Article 370 (1950–2019) defined its modern political status.', 'Pashmina shawl weaving, papier-mache (naqash), carpet weaving of Srinagar, walnut wood carving, and the Sozni embroidery tradition.', 'Urs at Hazratbal, Shikara festival, Lohri, Baisakhi, and the Hemis-linked celebrations in Ladakh-influenced Kargil.', 'Kashmiri (Koshur), Dogri, Pahari, Hindi, Urdu. Wazwan feast (36-course), Rogan josh, dum aloo, sheermal bread and the noon chai (salt tea).', 'Lal Ded (14th-century mystic poet), Sheikh ul-Alam (Nund Rishi, Sufi saint), Habba Khatal (poetess).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (15, 'Jharkhand', 'JH', 'East', 'Ranchi', 'A state of tribal art, forests, waterfalls and the Sarna beliefs of the Adivasi communities.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The land of forests — where the Munda, Santhal, Ho and Oraon tribal communities preserve the Sarna animist faith and the Sarhul spring celebration.', 'Part of the Chotanagpur plateau kingdoms, Jharkhand was carved from Bihar in 2000. The tribal Sarna faith, Birsa Munda''s Ulgulan (rebellion) against the British (1899–1900), and the Mundari oral epic traditions define its cultural identity.', 'Sohrai and Khovar painting of the Santhal-Munda homes, Dokra metal craft, bamboo craft, and the paitkar scroll painting.', 'Sarhul (spring), Karma (monsoon), Tusu Parab, Sohrai (harvest), and the Jagannath Rath Yatra of Ranchi.', 'Hindi, Santhali, Mundari, Ho. Dhuska, rugda (mushroom curry), handia (rice beer) and the tribal forest-food cuisine.', 'Birsa Munda (tribal freedom fighter), Komaram Bhil (land-rights activist), Budho Dev (Santhal leader).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (16, 'Karnataka', 'KA', 'South', 'Bengaluru', 'Land of the Vijayanagara empire, classical Carnatic music, Channapatna toys and Mysuru silk.', 'The Kadambas to Chalukyas to Hoysalas, the mighty Vijayanagara imperium of Hampi, the Wodeyar principality of Mysuru and Tipu Sultan''s of Aaft Mode deeds.', 'Carnatic music of the Mysuru durbar, Yakshagana, Kuchipudi-adjacent coastal dance, and the Pune-in-Mysuru royal artisans.', 'Dasara of Mysuru (the royal 9-day), Hulivesha tiger dance and the Kargil-like Hampi lamp cermonies.', 'Channapatna wooden toys, Mysuru silk sarees, Udupi lamps and Sandalwood carving.', 'Mysuru masala dosa, Bisi bele bath, Coorg pandi curry and the jarringly sweet Mysore pak.', 'Mysuru Dasara|Hampi Utsav|Udupi Paryaya|Kambala suit-race|Ganesha Chaturthi', 'The Battle of Talikota (1565) which shattered Vijayanagara; the Anglo-Mysore Wars against Tipu.', '', 'The cradle of Vijayanagara, classical Carnatic music, Mysuru silk and Channapatna toys — a state where Hoysala temples, Yakshagana theatre and IT modernity coexist.', 'From the Kadamba and Chalukya dynasties through the Hoysalas to the glorious Vijayanagara empire (1336–1646), Karnataka has been a seat of South Indian power. Tipu Sultan''s kingdom at Srirangapatna, the Wodeyar dynasty of Mysuru and the modern Bengaluru IT boom layer its history.', 'Channapatna wooden toys, Mysuru silk sarees, Ilkal sarees, Bidriware (Bidar), and the stone-carved Hoysala temples of Belur and Halebid.', 'Mysuru Dasara (nine-day royal procession), Hampi Utsav, Karaga festival (Bengaluru), Kambala buffalo race, and the Yakshagana night-long performances.', 'Kannada (primary), Tulu, Konkani, Kodava. Bisi bele bath, Mysore masala dosa, Coorg pandi curry, Mysore pak and the filter coffee of Udupi.', 'Kempegowda (founder of Bengaluru), Tipu Sultan (resistance hero), Dr. Rajkumar (Kannada cinema icon).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (17, 'Kerala', 'KL', 'South', 'Thiruvananthapuram', 'God''s own country — Kathakali, Kalaripayattu, backwaters and Kerala mural art.', 'The Chera and Zamorin kingdoms traded spices with West Asia, Rome and China; the princely state of Travancore led literacy and social reform into the modern era.', 'Kathakali and Mohiniyattam, Theyyam ritual theatre, sopana music and the southern rigour of Kochi''s carnival of arts.', 'Theyyam performances, Onam boat races and the Vishu festival of golden blossoms.', 'Cheriyal/Nilambur woodwork, coir craft, mural painting, and Kuthambalam temple art.', 'Sadhya feast on plantain leaf, appam-puttu and ishtu, karimeen fry and the cheer of the toddy (kallu) shops.', 'Onam|Vallam Kali|Theyyam|Kathakali Festival|Kochi-Muziris Biennale', 'The naval expeditions of the Zamorins and the Kozhikode-Kochi rivalry forged by the pepper trade.', '', 'God''s Own Country — Kathakali, Kalaripayattu, backwaters and the ancient spice-trade cosmopolitanism of the Malabar coast.', 'The Chera dynasty, the Zamorins of Calicut, the Cochin Jewish community and the Travancore royal house shaped Kerala''s layered heritage. The spice trade drew Romans, Arabs, Portuguese, Dutch and British. Kerala''s 100% literacy and social reforms make it a model of human development.', 'Kathakali and Mohiniyattam costumes, Theyyam masks, coir rope-making, Kerala mural painting, and the Aranmula metal mirror craft.', 'Onam (harvest), Thrissur Pooram (elephant festival), Theyyam performances, Vishu, and the Kerala School Kalaripayattu festival.', 'Malayalam, Tulu (Kasargod). Sadhya feast on plantain leaf, appam-stew, karimeen pollichathu, and the Toddy Shop cuisine of the Malabar coast.', 'Chattampi Swamikal (social reformer), Sree Narayana Guru (philosopher), Rabindranath Tagore (visited Shantiniketan-Kerala connections).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (18, 'Ladakh', 'LA', 'North', 'Leh', 'A high-altitude land of Buddhist gompas, monasteries and the Hemis festival.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The roof of India — a high-altitude Buddhist land of gompas, masked cham dances and the nomadic Changpa pastoral heritage of the Great Himalayan range.', 'Part of the ancient Silk Route connecting Central Asia with the Indian plains, Ladakh was a Buddhist kingdom for over a millennium. The Hemis, Thiksey and Alchi monasteries date from the 11th century. Became a union territory in 2019 after being part of Jammu & Kashmir.', 'Thangka painting, Pashmina (Changpa goat) weaving, silver and turquoise jewellery, and the papier-mache masks of the cham dance.', 'Hemis festival (June–July), Losar (New Year), Spituk Gustor, and the Sindhu Darshan festival.', 'Ladakhi (Bhoti), Hindi, Urdu. Thukpa, momos, skyu (pasta stew), butter tea (po cha) and chang (barley beer).', 'Rinchen Zangpo (10th-century translator-builder), Swami Vivekananda (visited Ladakh references).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (19, 'Lakshadweep', 'LD', 'Islands', 'Kavaratti', 'A coral archipelago with a distinct island Muslim culture and traditional coral-boat building.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'India''s coral archipelago — a Muslim-majority island territory of matrilineal customs, coral-boat building and the pristine marine heritage of the Arabian Sea.', 'Inhabited since the 1st century CE by Dravidian and later Arab traders, the islands came under Tipu Sultan''s control and then the British. The Aminidivi, Maliku and other atolls preserve a distinct island culture linked to the Malabar coast.', 'Coir rope-making, traditional coral-boat (oddi) building, and the Thachushasthram wood-carving tradition.', 'Bakrid celebrations, Muharram, Onam (among Hindu families), and the island boat-race festivals.', 'Malayalam (Mahl dialect), Hindi. Coconut-based seafood cuisine, octopus curry, and the rice-and-fish staple.', 'P.M. Sayeed (former Union Minister from Lakshadweep).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (20, 'Madhya Pradesh', 'MP', 'Central', 'Bhopal', 'Heart of India — home to Khajuraho, Sanchi and Gond tribal painting traditions.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The Heart of India — Khajuraho''s temples, Sanchi''s stupas, Gond tribal painting and the ancient caves of Bhimbetka, where 30,000 years of human artistry remain visible.', 'Madhya Pradesh has been the crossroads of Indian civilisation — the Maurya, Gupta, Parmar, Chandela and Mughal empires all left their mark. Khajuraho (950–1050 CE), Sanchi (3rd c. BCE), and the Bhimbetka rock shelters (30,000 years old) are UNESCO treasures.', 'Gond and Bhil tribal painting, Chanderi and Maheshwari silk sarees, Bagh block printing, and the bronze-casting traditions of Bastar and Sagar.', 'Khajuraho Dance Festival, Tansen Music Festival (Gwalior), Bhagoria (tribal spring), and the Narayanpet craft fair.', 'Hindi, Malvi, Bundeli, Gondi. Poha-jalebi, bhutte ka kees, dal bafla, and the mawa-bati of Indore.', 'Tansen (Mughal musician, born in Gwalior), Raja Bhoj (Parmar king, Bhopal), Gond queen Rani Durgavati.', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (21, 'Maharashtra', 'MH', 'West', 'Mumbai', 'The land of the Marathas — hill forts of the Sahyadri, the vibrant Ganeshotsav public festival, film heritage and the Ajanta-Ellora caves. The ministry ecosystem here includes ASI-protected forts, museums and an active archival tradition.', 'Home to the Satavahana kingdom, the Yadavas of Devagiri, the Bahmani-Adilshahi courts and the great Maratha empire founded by Chhatrapati Shivaji Maharaj. Pune served as the seat of the Peshwas and the Maratha confederacy from the early 18th century.', 'Known for classical music (Gwalior and Kirana gharanas), tamasha and sangeet natak theatre, the wada architecture of the Peshwa era, and the city-based Ganpati culture started by Lokmanya Tilak.', 'Ganeshotsav, Gudi Padwa, Chhatrapati Shivaji Maharaj Jayanti processions and the spectacular Shukravar peth lighting; Warkari pilgrimages to Pandharpur follow the dindi path.', 'Paithani and Himroo textiles, Kolhapuri chappals, Mashru pattani weaves and the lacquer craft of Phullanpurwa.', 'Puran poli, Misal pav, Vada pav, Bhelpuri, Shrikhand, Kolhapuri cuisine and the legendary family-run bakeries and Irani cafes of Pune and Mumbai.', 'Ganeshotsav|Gudi Padwa|Shivaji Jayanti|Gunpowder Jatra of Nashik|Kala Ghoda Arts Festival', 'The Battle of Sinhagad (1670) — Tanaji Malusare''s capture of the fort; the Panipat campaign (1761); the conquest of Raigad and the establishment of the Maratha Confederacy.', '', 'The land of the Marathas — hill forts of the Sahyadri, Ganeshotsav, Ajanta-Ellora caves and a vibrant film and literary culture.', 'Home to the Satavahanas, Yadavas of Devagiri, the Bahmani-Adilshahi courts and the great Maratha empire of Chhatrapati Shivaji Maharaj. Pune was the Peshwa seat. The 1857 uprising, Lokmanya Tilak''s Ganeshotsav and Ambedkar''s social reforms define its modern chapter.', 'Paithani and Himroo textiles, Kolhapuri chappals, Warli painting, Ganpati idol craft, and the lacquer work of Phullanpurwa.', 'Ganeshotsav, Gudi Padwa, Shivaji Jayanti, Kala Ghoda Arts Festival, and the Warkari pilgrimages to Pandharpur.', 'Marathi, Konkani. Puran poli, misal pav, vada pav, shrikhand, Kolhapuri cuisine and Irani cafes of Pune.', 'Chhatrapati Shivaji Maharaj, Lokmanya Tilak, Dr. B.R. Ambedkar, Lata Mangeshkar.', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (22, 'Manipur', 'MN', 'Northeast', 'Imphal', 'Birthplace of Ras Lila dance and indigenous polo; a state of lush valleys and martial traditions.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The Jewel of India — birthplace of Ras Lila dance, indigenous polo (Sagol Kangjei) and the martial Moirang heritage of the Meitei people.', 'The Meitei kingdom of Manipur, with its Vaishnavite transformation under King Pamheiba (18th c.), has a unique script (Meitei Mayek) and the Ras Lila dance tradition. The Battle of Imphal (WWII) was a turning point in the Pacific theatre.', 'Manipuri Ras Lila costumes, Manipuri textile (phanek, innaphi), and the Moirangphee weaving tradition.', 'Yaoshang (Holi), Sangai Festival (November), Ningol Chakouba, and the Ras Lila performances at the Govindaji Temple.', 'Meitei (Manipuri), Thadou-Kuki. Eromba (fermented fish), kangshoi (vegetable stew), and the fish-fermentation (ngari) culture.', 'Rajarshi Bhagyachandra (king-patron of Ras Lila), Irom Chanu Sharmila (peace activist).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (23, 'Meghalaya', 'ML', 'Northeast', 'Shillong', 'The abode of clouds — matrilineal Khasi, Jaintia and Garo cultures amidst living-root bridges.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The Abode of Clouds — a matrilineal Khasi, Jaintia and Garo society with living-root bridges, the living root bridges of Cherrapunji and a vibrant music culture.', 'Part of Assam until 1972, Meghalaya was formed as an autonomous state for the Khasi, Jaintia and Garo tribes. The Khasi Hills and Jaintia Hills preserve matrilineal inheritance and a distinct monsoon-adapted architecture.', 'Khasi bamboo basketry, Jaintia stone carving, the Wangala drum craft of the Garos, and the living-root bridge engineering.', 'Nongkrem dance (Khasi harvest), Wangala (Garo thanksgiving), Behdeinkhlam (Jaintia), and the Cherry Blossom Festival of Shillong.', 'Khasi, Jaintia, Garo, Hindi, Bengali. Jadoh (red rice pork), tungrymbai (fermented soybean), dohneiiong (pork with black sesame).', 'Dr.ディング-du-on (first Chief Minister of Meghalaya), Williams Sangma (Garo leader).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (24, 'Mizoram', 'MZ', 'Northeast', 'Aizawl', 'A vibrant state of Mizo hymn culture, festivals like Chapchar Kut and handloom shawls.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The Land of the Hill People — a state of Mizo hymn culture, bamboo dance (Cheraw) and the Chapchar Kut spring festival.', 'Mizoram was part of Assam until 1972 and became a full state in 1987. The Mizo people''s conversion to Christianity (19th–20th c.) and their communal ''kawtlawh'' (joint venture) traditions shape the modern state''s unique character.', 'Pawndum weaving (Mizo textile), basketry, and the arm-ring silver craft.', 'Chapchar Kut (spring), Thalfavang Kut, Pawl Kut (harvest), and the Anthurium Festival.', 'Mizo (Tlawng), Hindi. Bai (boiled vegetable stew), sawhchiar (rice and meat), and the bamboo-shoot-based cuisine.', 'Laldenga (Mizo leader, first CM), Ramtharliana (poet).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (25, 'Nagaland', 'NL', 'Northeast', 'Kohima', 'Land of the Naga tribes, the Hornbill Festival and spectacular warrior heritage.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'Land of the Naga tribes — a warrior heritage expressed through the Hornbill Festival, warrior shawls and the head-hunting traditions of the Angami, Ao and Sumi tribes.', 'Nagaland was part of Assam until 1963 when it became a state. The 16-odd Naga tribes maintained fierce independence until British contact (19th c.). The Naga peace process and the annual Hornbill Festival reflect the transition from warrior tradition to cultural celebration.', 'Naga shawl weaving (each tribe has its own pattern), wood-carving, bead-work and the warrior head-hunting ceremonial gear.', 'Hornbill Festival (Kisama), Moatsu, Sekrenyi (Angami), Aoling (Konyak) and the dead rice festival of the Ao.', 'Naga tribal languages (Ao, Angami, Sumi, etc.), Hindi. Smoked pork with bamboo shoot, axone (fermented soybean), and the fiery Naga chilli cuisine.', 'Rani Gaidinliu (freedom fighter), Hiteswar Saikia (Assam CM of Naga origin).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (26, 'Odisha', 'OD', 'East', 'Bhubaneswar', 'Land of the Sun Temple at Konark, Jagannath culture, Pattachitra art and Odissi dance.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The Soul of India — Konark''s Sun Temple, the Rath Yatra of Puri, Pattachitra art and Odissi dance — a state where temple, craft and ritual are inseparable.', 'Kalinga''s maritime power, Ashoka''s conversion after the Kalinga war (261 BCE), the Ganga and Eastern Ganga dynasties built the Sun Temple at Konark (13th c.) and the Jagannath Temple at Puri. Odisha was carved from Bengal in 1936 and became a state in 1950.', 'Pattachitra scroll painting, silver filigree (Cuttack), Sambalpuri ikat weaving, Dhokra casting, and the stone-carving traditions of Puri-Konark.', 'Rath Yatra of Puri (Jagannath), Konark Dance Festival, Bali Jatra (Cuttack), and the Durga Puja celebrations.', 'Odia (Indo-Aryan). Pakhala (fermented rice), dalma, chhena poda (cheese dessert), and the Mahaprasad of the Jagannath Temple.', 'Sarala Devi (first Odia woman novelist), Biju Patnaik (freedom fighter and CM), Sonali Kulkarni (cultural activist).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (27, 'Puducherry', 'PY', 'South', 'Puducherry', 'A former French enclave blending Tamil traditions with boulevard architecture.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The French Riviera of the East — a former French enclave where Tamil temple culture meets boulevard architecture and Auroville''s experimental spirituality.', 'French colonial rule (1674–1954) left a bilingual, bicultural legacy. Sri Aurobindo''s ashram (1926) and the experimental township of Auroville (1968) added a spiritual-international dimension to this small territory.', 'Auroville''s craft workshops (pottery, paper-making, incense), Tamil bronze casting, and the French Quarter''s artistic studios.', 'Bastille Day (July 14), Pongal, the Auroville birthday celebration, and the Pondicherry Heritage Festival.', 'Tamil, French (heritage language). Franco-Tamil cuisine — bouillabaisse-Tamil fusion, filter coffee, and the boulangerie culture of the French Quarter.', 'Sri Aurobindo, The Mother (Mirra Alfassa), Joseph François Dupleix (French governor).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (28, 'Punjab', 'PB', 'North', 'Chandigarh', 'The land of the Gurus — Bhangra, folk music, and the sacred city of Amritsar.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The Land of the Five Rivers — home of the Golden Temple, Bhangra, Sufi qawwali and the Jallianwala Bagh memory that forged modern India''s conscience.', 'The Sikh Gurus established Amritsar and the Khalsa tradition. The Ranjit Singh empire (1799–1849) unified Punjab before British annexation. Jallianwala Bagh (1919), the Partition (1947) and the Green Revolution shaped modern Punjab.', 'Phulkari embroidery, Patiala salwar-kameez, the brass and copper craft of Amritsar, and the handloom weaving of Thevara.', 'Baisakhi, Lohri, Holla Mohalla (Sikh martial festival), the Golden Temple illumination, and the Rural Olympics of Kila Raipur.', 'Punjabi, Hindi. Makki di roti with sarson ka saag, butter chicken, Amritsari kulcha and the lassi culture.', 'Guru Nanak (founder of Sikhism), Baba Deep Singh (martyr), Bhagat Singh (freedom fighter).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (29, 'Rajasthan', 'RJ', 'North', 'Jaipur', 'The desert kingdom of forts, palaces, folk music, camel fairs and miniature painting — one of the most heritage-dense states of India.', 'Founded by Rajput clans — Mewar, Marwar, Jaipur and Bundi. The state preserved Rajput martial and courtly civilisations, produced the famed Rajput painting schools and contributed decisively to the freedom movement.', 'Rajputana court culture, miniature painting, Kathak, Langa-Manganiyar folk music, puppet traditions (kathputli) and the living craft clusters of blue pottery and bandhani.', 'Gangaur, Teej, the camel fairs of Pushkar, and ornate wedding and temple rituals of Marwar.', 'Blue pottery of Jaipur, bandhani and leheriya, silver jewellery of Bikaner, Usta art and block printing of Sanganer.', 'Dal baati churma, Gatte ki sabzi, Laal maas, Mawa kachori and the street sweets of Jodhpur and Jaipur.', 'Pushkar Camel Fair|Jaipur Literature Festival|Teej & Gangaur|Jaisalmer Desert Festival|Udaipur World Music Festival', 'The siege and Jauhar of Chittorgarh; the Battle of Haldighati (1576) between Maharana Pratap and Akbar''s forces.', '', 'The desert kingdom — forts, palaces, folk music, camel fairs and miniature painting, where every city has a colour and every fort a saga.', 'Rajput clans — Mewar, Marwar, Jaipur and Bundi — preserved martial and courtly civilisation through centuries. The Rajput painting schools, the Shekhawati haveli tradition and the Pushkar camel fair are globally recognised cultural markers.', 'Blue pottery of Jaipur, Bandhani and Leheriya, block printing of Sanganer, silver jewellery of Bikaner, Usta art, and the Kathputli puppet tradition.', 'Pushkar Camel Fair, Jaipur Literature Festival, Gangaur, Teej, Jaisalmer Desert Festival, and the Mewar Festival.', 'Rajasthani (Marwari, Mewari, Dhundhari), Hindi. Dal baati churma, gatte ki sabzi, laal maas, mawa kachori.', 'Maharana Pratap (Mewar), Sawai Jai Singh II (founder of Jaipur), Mira Bai (saint-poetess).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (30, 'Sikkim', 'SK', 'Northeast', 'Gangtok', 'A Himalayan Buddhist state of monasteries, masked dances and the Pang Lhabsol festival.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'A Himalayan Buddhist kingdom-turned-state — monasteries, masked dances, organic farming and the Kanchenjunga worship of the Lepcha, Bhutia and Nepali communities.', 'The Namgyal dynasty ruled Sikkim for over 300 years until its merger with India in 1975. The Rumtek Monastery (seat of the Karmapa) and the Pang Lhabsol festival reflect the Tibetan Buddhist heritage.', 'Thangka painting, Chokse mask-carving, bamboo craft, and the traditional Bhutia wool-weaving.', 'Pang Lhabsol (warrior dance for Kanchenjunga), Losar, Saga Dawa, and the International Flower Exhibition.', 'Nepali (dominant), Lepcha, Bhutia, Hindi. Momos, thukpa, gundruk (fermented leafy greens), and chhang (barley beer).', 'Chogyal Tashi Namgyal (last king), Padmasambhava (associated with Sikkim''s founding legend).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (31, 'Tamil Nadu', 'TN', 'South', 'Chennai', 'Epicentre of Dravidian temple architecture, Bharatanatyam, and the lost-wax Chola bronze tradition.', 'Tamilakam''s Sangam literature, the Pallava and Chola dynasties, the Vijayanagara successor states of Madurai and Thanjavur, and the European colonial trading ports shaped a culture of extraordinary continuity.', 'Bharatanatyam, Carnatic music, Kuthu-folk theatre, Tamil film and literature, temple sculpture schools and the Tamil computing renaissance.', 'Pongal, Margazhi music season, the Natyanjali dance festival and elaborate agamic temple worship.', 'Chola bronzes, Tanjore paintings, Kanchipuram silks, bronze icons of Swamimalai and Chettinad woodcraft.', 'Idli, dosa, Pongal, Chettinad cuisine, filter coffee and the December season crescendos of tiffin culture.', 'Pongal|Natyanjali Dance Festival|Margazhi Music Season|Mahabalipuram Dance Festival|Thaipusam', 'The Battle of Takkolam (949) and the long Pallava-Chola-Chalukya contests over Kanchi and Thanjavur.', '', 'Epicentre of Dravidian temple architecture, Bharatanatyam, Carnatic music and the Chola bronze tradition — the oldest continuously inhabited cultural zone in South Asia.', 'Sangam literature (300 BCE–300 CE), the Pallava and Chola dynasties, the Nayak kingdoms and the British Madras Presidency shaped Tamil Nadu''s extraordinary civilisational continuity. The Tamil computing renaissance and the December Margazhi music season are modern markers.', 'Bharatanatyam, Chola bronzes, Tanjore paintings, Kanchipuram silks, bronze icons of Swamimalai, and Chettinad woodcraft.', 'Pongal, Natyanjali Dance Festival, Margazhi Music Season, Mahabalipuram Dance Festival, Thaipusam.', 'Tamil (Dravidian). Idli, dosa, Chettinad cuisine, filter coffee, the December season tiffin culture.', 'Thiruvalluvar (saint-poet), Raja Ravi Varma (painter), M.S. Subbulakshmi (Carnatic vocalist).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (32, 'Telangana', 'TG', 'South', 'Hyderabad', 'Land of the Qutb Shahi and Asaf Jahi courts — biryani, pearls, Deccan miniatures and Golconda.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The land of the Qutb Shahi and Asaf Jahi courts — biryani, pearls, Deccan miniature painting and the Golconda diamond legacy.', 'The Satavahanas, the Kakatiya dynasty (Warangal), the Bahmani and Qutb Shahi courts (Golconda, 1518–1687) and the Asaf Jahi Nizams (1724–1948) created a composite Deccan culture. Telangana became a separate state in 2014.', 'Deccani miniature painting, Bidriware, pearl-setting craft of Hyderabad, and the handloom weaving of Pochampally (UNESCO-recognised ikat).', 'Bathukamma (flower festival), Bonalu, Eid-Milad-un-Nabi processions, and the Hyderabad Literary Festival.', 'Telugu (Deccani dialect), Urdu. Hyderabadi biryani, haleem, double-ka-meetha, Irani chai and Osmania biscuits.', 'Quli Qutb Shah (founder of Hyderabad), Rani Rudrama Devi (Kakatiya queen), Sarojini Naidu (poet-freedom fighter).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (33, 'Tripura', 'TR', 'Northeast', 'Agartala', 'A state of royal ancestral temples (Chathuma) and the indigenous Kharchi festival.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'The land of the Manikya dynasty — royal ancestral temples, the Garia dance of the Tripuri tribes and the Ujjayanta Palace overlooking a lake.', 'The Manikya dynasty ruled Tripura for over 3,000 years until the 1949 merger with India. The state was part of Bengal before becoming a union territory (1956) and a full state (1972). The Kokborok language and the indigenous tribal festivals define its culture.', 'Handloom weaving (Risa, Rignai textiles), bamboo craft, and the wood-carving tradition of the Manikya palace.', 'Kharchi Puja (14 gods), Garia dance festival,Orange Festival, and the Tripura Literature Festival.', 'Bengali, Kokborok (Tripuri), Hindi. Gudok (bamboo shoot curry), chakhwi (meat and vegetable stew), and the rice-beer culture.', 'Bir Bikram Kishore Manikya (moderniser king), Sachin Debbarman (freedom fighter).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (34, 'Uttar Pradesh', 'UP', 'North', 'Lucknow', 'Heartland of the Ganga — Varanasi''s ghats, Ayodhya''s faith, Mathura''s Krishna and Lucknow''s nawabi culture.', 'The Gangetic heartland where the Buddha, Mahavira, the Guptas and the great nawabi courts of Awadh shaped two millennia of Indian civilisation.', 'Hindustani classical music of the Lucknow gharana, Banarasi weaving, Chikankari embroidery and the living Kumbh of sangam cities.', 'Ganga arti at Dashashwamedh ghat, Dev Deepawali, Kumbh Mela congregations and the Ramnagar evenings.', 'Banarasi silk saris, Chikankari, wooden toys of Varanasi, and the brassware of Moradabad.', 'Kashi chaat, Lucknowi biryani, Tunday kebabs, malaiyo and the petha of Agra.', 'Kumbh Mela|Dev Deepawali|Ganga Mahotsav|Lucknow Mahotsav|Kartik Mela', 'The Revolt of 1857 sieges of Lucknow and Kanpur; the medieval sack of Varanasi raids.', '', 'The heartland of the Ganga — Varanasi''s ghats, Ayodhya''s faith, Mathura''s Krishna, Lucknow''s nawabi culture and the Kumbh Mela, the largest human gathering on earth.', 'The Gangetic heartland where the Buddha, Mahavira, the Guptas and the Mughal court at Agra shaped two millennia of Indian civilisation. Varanasi''s 3,000-year-old continuity, Lucknow''s Nawabi culture, and the 1857 revolt are central to India''s story.', 'Banarasi silk saris, Chikankari embroidery, brassware of Moradabad, wooden toys of Varanasi, and the Lucknow Zardozi.', 'Kumbh Mela (Prayagraj), Dev Deepawali (Varanasi), Ganga Mahotsav, Lucknow Mahotsav, Ram Navami (Ayodhya).', 'Hindi, Braj, Awadhi, Bhojpuri. Kashi chaat, Lucknowi biryani, Tunday kebabs, malaiyo, and the petha of Agra.', 'Tulsidas (Ramcharitmanas), Kabir (saint-poet), Rani Lakshmibai (Jhansi, UP-linked).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (35, 'Uttarakhand', 'UK', 'North', 'Dehradun', 'Land of the Char Dham shrines, resilient hill culture and the Nanda Devi Raj Jat yatra.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'Dev Bhumi — the land of the Char Dham shrines, Garhwali-Kumaoni folk traditions and the sacred Himalayan pilgrim routes.', 'Part of the ancient Kumaon and Garhwal kingdoms, Uttarakhand was part of Uttar Pradesh until 2000. The Char Dham (Badrinath, Kedarnath, Gangotri, Yamunotri) pilgrimages and the Nanda Devi Raj Jat yatra are centuries-old traditions.', 'Aipan floor art, Bal Mithai (Almora sweet craft), ringal bamboo craft, and the wood-carved Himalayan temples.', 'Nanda Devi Raj Jat (12-year cycle), Phool Dei (spring), Ghee Sankranti, and the Kumaoni Holi (Baithki and Khari).', 'Hindi, Garhwali, Kumaoni. Kafuli (spinach curry), bal Mithai, singori (cone-wrapped sweet), and the jimuni cuisine of the hills.', 'Govind Ballabh Pant (freedom fighter, first CM of UP), Nain Singh Rawat (Tibet explorer).', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (36, 'West Bengal', 'WB', 'East', 'Kolkata', 'The cultural capital of Bengal — the Renaissance, Durga Puja, baul music and patachitra scroll art.', 'From the Pala and Sena kingdoms to the Nawabate of Murshidabad and the Bengal Presidency, Bengal was the spearhead of the 19th-century Indian Renaissance and the 1905-1947 freedom movements.', 'Bengali literature, Rabindra Sangeet, baul-fakir mystic music, jatra theatre, shola and conch crafts and the global-scale Durga Puja celebration.', 'Durga Puja pandals, the barowari exponent body (from 1790), Saraswati Puja, Rathayatra of Mahesh and the Ganga sangeet evenings.', 'Terracotta temples of Bishnupur, Baluchari and Tangail sarees, Shantiniketan leather craft and kantha embroidery.', 'Macher jhol, rosogolla, mishti doi, phuchka and the winter pitha platter.', 'Durga Puja|Rathayatra|Poush Mela|Kali Puja|Pohela Boishakh', 'The Battle of Plassey (1757) and the Battle of Buxar (1764) that decided the subcontinent''s colonial fate.', '', 'The cultural capital — Bengal Renaissance, Durga Puja, Baul music and Patachitra scroll art, where intellectual and artistic traditions shape daily life.', 'From the Pala and Sena kingdoms through the Nawabate of Murshidabad to the Bengal Presidency, Bengal led India''s 19th-century Renaissance and the freedom movement. The 1947 Partition, Tagore''s Shantiniketan, and the Durga Puja UNESCO listing define modern Bengal.', 'Patachitra scroll painting, Baluchari and Tangail sarees, Shantiniketan leather craft, Kantha embroidery, and the terracotta temples of Bishnupur.', 'Durga Puja (UNESCO Intangible Heritage), Rathayatra of Mahesh, Poush Mela (Shantiniketan), Kali Puja, Pohela Boishakh.', 'Bengali, Santhali, Nepali. Macher jhol, rosogolla, mishti doi, phuchka, and the winter pitha platter.', 'Rabindranath Tagore, Swami Vivekananda, Sri Aurobindo, Satyajit Ray.', 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11');
