  (2, 'A.L. Basham', 'Cambridge historian whose survey of ancient India remains the standard introduction.', 'Indology', '1914-1986', 'University of London', 'The Wonder That Was India', ''),
  (3, 'Rabindranath Tagore', 'Poet, novelist and polymath; translated his own Gitanjali into English.', 'Literature', '1861-1941', 'Visva-Bharati', 'Gitanjali, Gora', ''),
  (4, 'D.D. Kosambi', 'Independent Marxist-mathematician historian who recast ancient Indian history.', 'Indology', '1907-1966', 'Bombay', 'The Culture and Civilisation of Ancient India', ''),
  (5, 'C. Rajagopalachari', 'The ''keeper of the conscience of India''; wrote the enduring prose Mahabharata.', 'Literature & Dharma', '1878-1972', 'Madras', 'Ramayana/Mahabharata retellings', ''),
  (6, 'John Keay', 'Scottish historian of the subcontinent and the East India Company.', 'History', '1941-', '—', 'India: A History', ''),
