INSERT INTO "heritage_categories" ("id", "slug", "name", "kind", "parent_slug", "description", "image_url", "display_order") VALUES
  (1, 'man-made', 'Man-Made', 'tangible', NULL, 'Forts, palaces, temples, monuments, museums and historic structures created by human hands over the centuries.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Red_Fort_in_New_Delhi-2014-raj.jpg?width=900', 1),
  (2, 'natural', 'Natural', 'tangible', NULL, 'National parks, wildlife sanctuaries, forests and natural heritage landscapes of outstanding universal value.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaziranga_National_Park_in_Assam,_India.jpg?width=900', 2),
  (3, 'mixed', 'Mixed', 'tangible', NULL, 'Sites that combine significant natural and cultural characteristics within a single protected landscape.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Khangchendzonga_National_Park.JPG?width=900', 3),
  (4, 'classical-dance', 'Classical Dance', 'intangible', NULL, 'The codified classical dance traditions of India, from Bharatanatyam to Kathak and Odissi.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bharatanatyam_Performance_by_Namrita_Bhat.png?width=900', 10),
  (5, 'folk-dance', 'Folk Dance', 'intangible', NULL, 'Community folk dances expressing the joy, faith and rhythms of regional life.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Garba_dance_at_Navratri.jpg?width=900', 11),
  (6, 'classical-music', 'Classical Music', 'intangible', NULL, 'Hindustani and Carnatic classical music traditions passed down through guru-shishya lineages.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sitar_-_An_Introduction.jpg?width=900', 12),
  (7, 'folk-music', 'Folk Music', 'intangible', NULL, 'Regional folk and devotional music — from Baul songs of Bengal to the music of Rajasthan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhawaiya_Dance.jpg?width=900', 13),
  (8, 'folk-songs', 'Folk Songs', 'intangible', NULL, 'Oral song traditions of tribes and communities, sung at life-cycle, harvest and festival occasions.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baul_performance.jpg?width=900', 14),
  (9, 'theatre', 'Theatre', 'intangible', NULL, 'Classical and folk theatre traditions, from Sanskrit Kutiyattam to folk plays such as Ramlila.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ramlila,_Ram_nagar.jpg?width=900', 15),
  (10, 'traditional-performing-arts', 'Traditional Performing Arts', 'intangible', NULL, 'Martial arts, puppetry, ritual performances and other living performing traditions.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chhau_dance.jpg?width=900', 16),
  (11, 'traditional-crafts', 'Traditional Crafts', 'intangible', NULL, 'Craft traditions such as pottery, metalwork, marble work and inlay practised by hereditary artisans.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Blue_Pottery_Jaipur.jpg?width=900', 17),
  (12, 'handicrafts', 'Handicrafts', 'intangible', NULL, 'Hand-made objects — toys, jewellery, lacquerware and folk painting — rooted in regional aesthetics.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kondapalli_toys.jpg?width=900', 18),
  (13, 'textiles', 'Textiles', 'intangible', NULL, 'Handloom and hand-embroidery traditions, from Kanjeevaram silk to Phulkari and Pashmina.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pashmina_Weaving_Crafts.jpg?width=900', 19),
  (14, 'traditional-artistic-forms', 'Traditional Artistic Forms', 'intangible', NULL, 'Painting and visual art traditions — Madhubani, Pattachitra, Warli and miniature painting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Madhubani_Painting_(Bihar).jpg?width=900', 20),
  (15, 'festivals-cultural-practices', 'Festivals & Cultural Practices', 'intangible', NULL, 'Festivals, fairs and community celebrations that sustain cultural identity through the year.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Durga_Puja_at_Shobhabazar_Rajbari.jpg?width=900', 21),
  (16, 'rituals-traditions', 'Rituals & Traditions', 'intangible', NULL, 'Life-cycle rituals, sacred practices and inherited traditions observed by communities.', 'https://commons.wikimedia.org/wiki/Special:FilePath/_aarti_ganga.jpg?width=900', 22),
  (17, 'oral-traditions', 'Oral Traditions', 'intangible', NULL, 'Verbal traditions — epic narration, proverbs, mythologies and ritual chants.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pandavani_performers.jpg?width=900', 23),
  (18, 'storytelling', 'Storytelling', 'intangible', NULL, 'Grand narrative storytelling arts such as Harikatha, Burrakatha and Kathaprasangam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Harikatha_performance.jpg?width=900', 24),
  (19, 'traditional-knowledge', 'Traditional Knowledge', 'intangible', NULL, 'Indigenous knowledge systems in health, farming, martial arts and living sustainably.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Yoga_-_Surya_Namaskara.jpg?width=900', 25),
  (20, 'culinary', 'Culinary & Food Practices', 'intangible', NULL, 'Traditional foodways, recipes and the community practices surrounding them.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thali_meal.jpg?width=900', 26);
INSERT INTO "ministry_profile" ("id", "heading", "about", "mission", "vision", "attached_offices", "subordinate_offices", "autonomous_organizations", "directory_url", "organisations_url", "source_name", "source_url", "updated_at") VALUES
  (1, 'Ministry of Culture — Government of India', 'The Ministry of Culture is the nodal agency of the Government of India for the preservation, promotion and dissemination of India''s cultural heritage — tangible and intangible. It administers a vast ecosystem of museums, monuments, libraries, archives, academies and cultural institutions that protect and showcase the country''s civilisational legacy and connect citizens to their living traditions.', 'To preserve, protect and promote India''s vast and diverse cultural heritage and to connect every Indian — citizen and scholar alike — with the living traditions of the nation.', 'To position India as a global cultural hub where heritage is preserved as a living resource, researched with rigour, and shared with the world.', 8, 26, 39, 'https://www.indiaculture.gov.in/directory-of-officers', 'https://www.indiaculture.gov.in/subordinate-offices-and-autonomous-bodies', 'Ministry of Culture, Government of India', 'https://www.indiaculture.gov.in', '2026-09-09');
INSERT INTO "about_entries" ("id", "section", "title", "content") VALUES
  (1, 'mission', 'Mission', 'To preserve, promote and disseminate India''s rich cultural heritage and make it discoverable to every citizen.'),
  (2, 'mission', 'Mission', 'To unify the scattered digital resources of the cultural ecosystem into one intelligent, accessible experience.'),
  (3, 'objectives', 'Objectives', 'Unify fragmented cultural data into a single governed platform.'),
  (4, 'objectives', 'Objectives', 'Enable spatial discovery of heritage through interactive mapping.'),
  (5, 'objectives', 'Objectives', 'Preserve tangible and intangible heritage through digitisation and community participation.'),
  (6, 'objectives', 'Objectives', 'Provide trustworthy, source-grounded cultural answers through an AI assistant.'),
  (7, 'objectives', 'Objectives', 'Serve researchers, students, tourists and citizens in multiple Indian languages.'),
  (8, 'functions', 'Functions', 'Standardising and curating cultural data from ministry institutions.'),
  (9, 'functions', 'Functions', 'Managing the interactive state-city-resource exploration experience.'),
  (10, 'functions', 'Functions', 'Running a moderated community-preservation layer for photographs, experiences and reviews.'),
  (11, 'functions', 'Functions', 'Operating an attributed AI Cultural Assistant grounded in verified sources.'),
  (12, 'functions', 'Functions', 'Exposing open APIs for researchers and partner institutions.'),
  (13, 'team', 'Team', 'Hon''ble Minister of Culture — policy leadership and guidance (prototype placeholder).'),
  (14, 'team', 'Team', 'Minister of State — parliamentary overview.'),
  (15, 'team', 'Team', 'Platform team — Ministry of Culture digital wing with SIH innovators.'),
  (16, 'presentation', 'Presentation', 'A unified digital cultural discovery and preservation platform for the heritage and culture of India.');
INSERT INTO "announcements" ("id", "title", "date", "source", "summary", "url") VALUES
  (1, 'Ministry launches digitisation drive for rare manuscripts', '2026-08-28', 'Ministry of Culture', 'A nationwide coordination with IGNCA and state archives to digitise over 10 lakh manuscript folios under the National Manuscript Mission.', 'https://www.indiaculture.gov.in'),
  (2, 'Union Budget strengthens heritage conservation corpus', '2026-08-10', 'Ministry of Finance', 'Enhanced allocation for the National Culture Fund and conservation of ASI-protected monuments.', 'https://www.indiaculture.gov.in'),
  (3, 'Gandhi Peace Prize 2025 conferred', '2026-07-02', 'Ministry of Culture', 'The annual prize for outstanding contribution to peace was conferred in a ceremony at Rashtrapati Bhavan.', 'https://www.indiaculture.gov.in'),
  (4, 'Museum Modernisation Programme extended', '2026-06-15', 'Ministry of Culture', 'Thirty more museums will be upgraded under the Scheme for Modernisation of Museums including accessibility and digital galleries.', 'https://www.indiaculture.gov.in'),
  (5, 'Intangible heritage documentation grants announced', '2026-05-20', 'Ministry of Culture', 'Grants for safeguarding living traditions of the states under the Scheme for Safeguarding Intangible Cultural Heritage.', 'https://www.indiaculture.gov.in');
INSERT INTO "awards" ("id", "name", "year", "recipient", "field", "citation", "description", "official_url") VALUES
  (1, 'Tagore Award for Cultural Harmony', '2023', 'Not announced', 'Cultural Harmony', 'Awarded for promotion of cultural harmony, values of universal peace and artistic endeavours in the spirit of Tagore.', 'Biennial international award carrying ₹1 crore instituted on the 150th birth anniversary of the poet.', 'https://www.indiaculture.gov.in'),
  (2, 'Gandhi Peace Prize', '2022', 'Gita Press, Gorakhpur', 'Peace & Social Service', 'Given for promotion of non-violence and world peace in the spirit of Mahatma Gandhi.', 'An annual award carrying ₹1 crore instituted in 1995.', 'https://www.indiaculture.gov.in'),
  (3, 'Gandhi Peace Prize', '2020', 'Bangladesh Awami League', 'Peace & Democracy', 'Recognised for upholding democratic values and the liberation legacy in the subcontinent.', 'Annual award carrying ₹1 crore.', 'https://www.indiaculture.gov.in'),
  (4, 'Tagore Award for Cultural Harmony', '2019', 'V.A. Shiva Ayyadurai', 'Cultural Harmony & Innovation', 'Recognised for using technology in the preservation and intercultural reach of heritage.', 'Biennial award carrying ₹1 crore.', 'https://www.indiaculture.gov.in');
INSERT INTO "commemorations" ("id", "name", "period", "field", "contribution", "significance", "locations", "people", "related_events", "sources") VALUES
  (1, 'Mahatma Gandhi', '1869-1948', 'Freedom Movement & Non-violence', 'Led India''s non-violent struggle for freedom; his troika of truth (satya), non-violence (ahimsa) and trusteeship shaped the nation.', 'The Father of the Nation whose assassination led to the creation of the Gandhi Smriti and National Archives memorial circuits.', 'Porbandar, Rajkot, Ahmedabad, Delhi', 'Kasturba Gandhi, Sardar Patel, Nehru', 'Salt March 1930; Quit India 1942', 'Official Gandhi Heritage Portal'),
  (2, 'Rabindranath Tagore', '1861-1941', 'Literature & Composite Culture', 'Poet of Gitanjali and the first Asian Nobel laureate; founder of Shantiniketan/Visva-Bharati.', 'India''s greatest modern cultural ambassador and the symbol of the Bengal Renaissance.', 'Kolkata, Shantiniketan', 'Mahatma Gandhi, Victoria Ocampo', 'Gitanjali 1912; Nobel 1913', 'Ministry of Culture commemorative programmes'),
  (3, 'Chhatrapati Shivaji Maharaj', '1630-1680', 'Statecraft & Governance', 'Founded the Maratha swarajya with a navy, a fortified kingdom and the Hindavi swarajya ideal.', 'The gear of the Maratha heritage celebrations; his forts are ASI-protected monuments.', 'Rajgad, Raigad, Sinhagad, Pune', 'Jijabai, Tanaji Malusare, Sambhaji Maharaj', 'Sinhagad 1670; Coronation 1674', 'ASI Fort Heritage Index'),
  (4, 'Swami Vivekananda', '1863-1902', 'Spiritual & Cultural Revival', 'Carried India''s spiritual heritage to the Parliament of Religions (1893) and founded the Ramakrishna Mission.', 'A symbol of youth energy whose birth anniversary is celebrated as National Youth Day.', 'Kolkata, Chennai, Belur', 'Sri Ramakrishna, Sarada Devi', 'Chicago Address 1893; Mission founded 1897', 'Ministry of Culture youth programmes'),
  (5, 'Tyagaraja', '1767-1847', 'Carnatic Music', 'The composer-saint of the kritis — hundreds of devotional songs central to Carnatic music.', 'His annual aradhana is observed at Thiruvaiyaru as a living cultural festival.', 'Thiruvaiyaru, Thanjavur', 'His disciples, the Thanjavur court', 'Aradhana festival, January', 'State Culture Dept. aradhana programme');
