INSERT INTO "government_programmes" ("id", "title", "description", "category", "image_url", "official_url", "source_label", "source_url", "active", "sort_order") VALUES
  (1, '150 Years of Vande Mataram', 'A year-long nationwide commemoration of India''s National Song ''Vande Mataram'' (7 November 2025 – 7 November 2026), inaugurated by the Prime Minister of India.', 'Commemoration', '/images/campaigns/vande-mataram-showcase-square.webp', 'https://www.vandemataram150.in', 'Ministry of Culture', 'https://culture.gov.in/commemorations/150-years-vande-mataram', 1, 1),
  (2, '80 Years of India''s Independence — Har Ghar Tiranga', 'The nationwide Har Ghar Tiranga campaign, launched by the Government of India, urging every citizen to hoist the Tiranga as India marks 80 years of independence on 15 August 2026.', 'Campaign', '/images/campaigns/har-ghar-tiranga.jpg', 'https://www.culture.gov.in', 'Ministry of Culture', 'https://pib.gov.in', 1, 2),
  (3, 'Gyan Bharatam Mission', 'The Ministry of Culture''s national mission to survey, conserve and digitise India''s manuscript heritage, including the National Manuscript Survey launched in March 2026.', 'Programme', '/images/campaigns/gyan-bharatam-showcase-square.webp', 'https://culture.gov.in/gyan-bharatam-mission', 'Ministry of Culture', 'https://culture.gov.in/gyan-bharatam-mission', 1, 3),
  (4, 'Indian Culture Portal (Version 2.0)', 'The Government of India''s national digital platform for India''s cultural heritage — manuscripts, art, monuments, museums and curated collections, upgraded in March 2026.', 'Portal', '/images/campaigns/indian-culture-showcase-square.webp', 'https://www.indianculture.gov.in', 'Ministry of Culture', 'https://www.indianculture.gov.in', 1, 4);
