INSERT INTO "schemes" ("id", "name", "description", "category", "eligibility", "benefits", "application_info", "year", "organization", "official_url") VALUES
  (1, 'Tagore National Fellowship for Cultural Research (TNFR)', 'One-year academic fellowships for research on Indian culture in museums, archives and libraries.', 'Fellowship', 'Indian nationals with a research proposal; postgraduate degree preferred.', 'Monthly fellowship + contingency grant; access to partner institutions.', 'Apply through the Annual Plan of the Ministry''s Research Programmes.', 'Ongoing', 'Ministry of Culture', 'https://www.indiaculture.gov.in/schemes'),
  (2, 'Scheme for Safeguarding Intangible Cultural Heritage', 'Grants to institutions, NGOs and academies for documenting and preserving living cultural heritage.', 'Yojana', 'Registered cultural bodies, universities and recognized academies.', 'Financial support up to 100% of approved project cost subject to caps.', 'Proposals invited through the ministry''s Intangible Heritage portal window.', 'Ongoing', 'Ministry of Culture', 'https://www.indiaculture.gov.in/schemes'),
  (3, 'Scheme for Modernisation of Museums (SMM)', 'Infrastructure, conservation and digital upgrade of museums across the country.', 'Financial Assistance', 'Government and government-aided museums.', 'Support for conservation labs, galleries, digitisation and audience programmes.', 'Submitted through the National Culture Fund line of the ministry.', '5th phase 2025', 'Ministry of Culture', 'https://www.indiaculture.gov.in/schemes'),
  (4, 'National Culture Fund', 'Mobilises public-private partnership resources for conservation of monuments and heritage.', 'Financial Assistance', 'Corporates under CSR; private donors; foundations.', 'Tax benefit under CSR for conservation projects.', 'Partnerships listed on the NCF portal.', 'Ongoing', 'National Culture Fund', 'https://culturefund.in'),
  (5, 'Cultural Economy and Dawn of the Cultural Sector grants', 'Seed grants for crafts, music, heritage tourism and creative industries startups.', 'TCC', 'India-registered startups and MSMEs in culture and creative sectors.', 'Up to ₹25 lakh seed support + mentoring.', 'Online application via the ministry cultural-industry window.', '2026-27', 'Ministry of Culture', 'https://www.indiaculture.gov.in/schemes'),
  (6, 'Special Anniversary Schemes for Important Personalities', 'Commemoration programmes marking the birth/death anniversaries of national personalities.', 'Anniversary Schemes', 'Cultural institutions and academies.', 'Funding for exhibitions, publications and memorial events.', 'Approved under the annual commemorations list.', 'Annual', 'Ministry of Culture', 'https://www.indiaculture.gov.in/schemes');
INSERT INTO "trending_items" ("id", "title", "slug", "category", "kind", "state", "city", "image_url", "image_position", "summary", "external_url", "explore_url", "trends_on", "current_event_score", "recent_activity_score", "cultural_significance_score", "user_interest_score", "recency_score", "trend_score", "source_name", "source_url", "is_active", "published_at", "created_at", "updated_at") VALUES
  (1, 'Somnath Temple', 'somnath-temple', 'Heritage Site', 'heritage', 'Gujarat', 'Somnath', '/images/trending/somnath.jpg', 'center', 'One of the twelve Jyotirlingas and a landmark of India''s coastal heritage, the Somnath temple at Prabhas Patan has been a centre of pilgrimage for over a thousand years. Its Chalukya-style shikhara and seaside setting make it a powerful symbol of cultural continuity and resilience.', 'https://www.somnath.org/', '/explore/heritage/somnath-temple', 0, 92.0, 88.0, 98.0, 94.0, 86.0, 91.8, 'Shree Somnath Trust / ASI', 'https://www.somnath.org/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (2, 'Group of Monuments at Hampi', 'hampi', 'Heritage Site', 'heritage', 'Karnataka', 'Hampi', '/images/heritage/hampi.jpg', 'center', 'The spectacular ruins of the Vijayanagara capital — a UNESCO World Heritage Site — spread across a surreal boulder-strewn landscape beside the Tungabhadra. Virupaksha Temple and the stone chariot rank among India''s greatest surviving expressions of Dravidian architecture.', 'https://whc.unesco.org/en/list/241/', '/explore/heritage/hampi', 0, 88.0, 90.0, 97.0, 92.0, 84.0, 90.3, 'UNESCO World Heritage Centre', 'https://whc.unesco.org/en/list/241/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (3, 'Konark Sun Temple', 'konark-sun-temple', 'Heritage Site', 'heritage', 'Odisha', 'Konark', '/images/heritage/konark.jpg', 'center', 'The colossal 13th-century ''Black Pagoda'' built by King Narasimhadeva I, conceived as a giant stone chariot of the Sun God drawn by seven horses. Its intricately carved wheels and temple sculpture make it a pinnacle of Kalinga architecture and a UNESCO World Heritage Site.', 'https://whc.unesco.org/en/list/246/', '/explore/heritage/konark-sun-temple', 0, 86.0, 84.0, 96.0, 90.0, 82.0, 87.5, 'UNESCO / ASI', 'https://whc.unesco.org/en/list/246/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (4, 'Red Fort', 'red-fort', 'Heritage Site', 'heritage', 'Delhi', 'Delhi', '/images/trending/red-fort.jpg', 'center', 'The massive red-sandstone fort of Shah Jahan, built in 1648 and the backdrop for India''s Independence Day addresses every year. Its Diwan-i-Khas, Moti Masjid and the raised marble pavilions embody the peak of Mughal imperial architecture.', 'https://whc.unesco.org/en/list/231/', '/explore/heritage/red-fort', 0, 90.0, 86.0, 95.0, 91.0, 85.0, 89.6, 'UNESCO / ASI', 'https://whc.unesco.org/en/list/231/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (5, 'Ajanta & Ellora Caves', 'ajanta-ellora-caves', 'Heritage Site', 'heritage', 'Maharashtra', 'Aurangabad / Chhatrapati Sambhajinagar', '/images/heritage/ajanta.jpg', 'center', 'Two rock-cut marvels of Buddhist, Hindu and Jain art. Ajanta''s painted murals narrate the Jataka tales, while Ellora''s Kailasa — carved top-down from a single rock — is a triumph of engineering and devotion spanning over six centuries.', 'https://whc.unesco.org/en/list/242/', '/explore/heritage/ajanta-ellora-caves', 0, 84.0, 82.0, 96.0, 89.0, 80.0, 86.0, 'UNESCO / ASI', 'https://whc.unesco.org/en/list/242/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (6, 'Shivaram Rajguru Heritage, Rajgurunagar', 'shivaram-rajguru-heritage', 'Heritage Site', 'heritage', 'Maharashtra', 'Rajgurunagar (Khed)', '/images/trending/rajguru.jpg', 'center', 'Rajgurunagar (Khed) is the birthplace of freedom fighter Shivaram Hari Rajguru, whose supreme sacrifice alongside Bhagat Singh and Sukhdev shook colonial rule. The Samadhi and memorial here keep alive a vital thread of India''s regional revolutionary heritage.', 'https://www.maharashtra.gov.in/', '/explore/heritage/shivaram-rajguru-heritage', 0, 78.0, 80.0, 88.0, 82.0, 88.0, 81.9, 'Government of Maharashtra', 'https://www.maharashtra.gov.in/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (7, 'Deepavali', 'deepavali', 'Festival', 'culture', 'Nationwide', NULL, '/images/trending/deepavali.jpg', 'center', 'The Festival of Lights, celebrated across India and the diaspora as the victory of light over darkness. From traditional oil lamps (diyas) and rangoli to feasts and fireworks, Deepavali is one of the most widely observed living festivals of Indian culture.', 'https://whc.unesco.org/en/list/', '/explore/culture/deepavali', 0, 96.0, 93.0, 90.0, 95.0, 82.0, 92.55, 'Ministry of Culture', 'https://culture.gov.in/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (8, 'Chhath Mahaparva', 'chhath-mahaparva', 'Festival', 'culture', 'Bihar | Jharkhand | UP', NULL, '/images/trending/chhath.jpg', 'center', 'An ancient festival dedicated to the Sun God and Chhathi Maiya, observed at the banks of rivers and ponds with offerings to the rising and setting sun. Chhath''s four days of austerity and devotion form one of India''s deepest expressions of living folk heritage.', 'https://whc.unesco.org/en/list/', '/explore/culture/chhath-mahaparva', 0, 97.0, 94.0, 89.0, 93.0, 92.0, 93.75, 'State Cultural Departments', 'https://culture.gov.in/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (9, 'Ol Chiki Script', 'ol-chiki-script', 'Living Culture', 'culture', 'Jharkhand', NULL, '/images/trending/ol-chiki.png', 'center', 'The recognised script of the Santali language, created by Pandit Raghunath Murmu in 1925 to preserve and revitalise the literary heritage of the Santal people. Ol Chiki embodies the living, written identity of one of India''s largest Adivasi communities.', 'https://www.unicode.org/versions/Unicode5.1.0/', '/explore/culture/ol-chiki-script', 0, 80.0, 86.0, 88.0, 80.0, 90.0, 84.1, 'UNESCO / Unicode Consortium', 'https://www.unicode.org/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (10, 'Garba', 'garba', 'Dance / Festival', 'culture', 'Gujarat', 'Nationwide (Navratri)', '/images/trending/garba.jpg', 'center', 'The circular, clapping folk dance of Gujarat performed during the nine nights of Navratri — now a UNESCO-listed intangible cultural heritage. Garba''s graceful rhythmic circles unite communities in celebration of the Goddess and of living tradition.', 'https://ich.unesco.org/en/RL/garba-of-gujarat-01686', '/explore/culture/garba', 0, 95.0, 92.0, 87.0, 93.0, 86.0, 91.55, 'UNESCO Intangible Heritage', 'https://ich.unesco.org/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (11, 'Chhau Dance', 'chhau-dance', 'Performing Art', 'culture', 'Odisha | Jharkhand | WB', NULL, '/images/trending/chhau.jpg', 'center', 'A martial, masked classical- folk dance from eastern India, UNESCO-listed as intangible cultural heritage. Chhau''s vigorous movements, elaborate masks and musical narrative carry centuries of ritual and martial tradition across Odisha, Jharkhand and West Bengal.', 'https://ich.unesco.org/en/RL/chhau-dance-00337', '/explore/culture/chhau-dance', 0, 82.0, 84.0, 90.0, 83.0, 84.0, 84.4, 'UNESCO Intangible Heritage', 'https://ich.unesco.org/', 1, '2026-09-09', '2026-09-09', '2026-09-09'),
  (12, 'Bharat Parv & Regional Traditions', 'bharat-parv-regional-traditions', 'Living Culture', 'culture', 'Nationwide', NULL, '/images/trending/bharat-parv.jpg', 'center', 'Bharat Parv celebrates India''s unity in diversity — folk and classical performance, regional crafts, cuisines and living traditions assembled from across the states. It is a moving showcase that the soul of India''s heritage is regional, rural and continuously alive.', 'https://culture.gov.in/', '/explore/culture/bharat-parv-regional-traditions', 0, 85.0, 88.0, 85.0, 86.0, 90.0, 86.35, 'Ministry of Culture', 'https://culture.gov.in/', 1, '2026-09-09', '2026-09-09', '2026-09-09');
