INSERT INTO "media_leaders" ("id", "name", "slug", "bio", "image_url", "official_url", "display_order") VALUES
  (1, 'Mahatma Gandhi', 'mahatma-gandhi', 'Mahatma Gandhi, born Mohandas Karamchand Gandhi on October 2, 1869, in Porbandar, Gujarat, is one of the most revered leaders in the history of India and a global symbol of non-violent resistance and civil rights. Gandhi''s philosophy and methods of non-violence and truth, known as Satyagraha, had a profound influence on movements for civil rights and freedom across the world.
