INSERT INTO "media_sanskriti" ("id", "title", "slug", "description", "image_url", "official_url", "source_label", "display_order") VALUES
  (1, 'Bharat: The Mother of Democracy', 'bharat-the-mother-of-democracy', 'A tribute to India’s unbroken democratic ethos, tracing its roots from ancient times to the present day. Curated by IGNCA, it shows how the idea of people’s participation in governance has been intrinsic to Indian civilisation for over 5,000 years — from the Sabhas and Samitis of the Vedas to the self-governing republics of ancient India, told through scriptures, inscriptions, coins and immersive exhibits.', '/images/media/sanskriti/bharat-the-mother-of-democracy.jpg', 'https://culture.gov.in/bharat-mother-democracy-2', 'Ministry of Culture · Sanskriti', 0),
  (2, 'Unsung Heroes of India’s Freedom Struggle', 'unsung-heroes', 'An attempt to recall and remember the forgotten heroes of India’s freedom struggle — stories of valour, bravery, Satyagraha, dedication and sacrifice from across the subcontinent, told by the Ministry of Culture as part of Azadi Ka Amrit Mahotsav.', '/images/media/sanskriti/unsung-heroes-freedom-struggle.png', 'https://culture.gov.in/unsung-heroes-of-indias-freedom-struggle', 'Ministry of Culture · Sanskriti', 1),
  (3, 'Digital District Repository', 'digital-district-repository', 'A repository that documents stories of people, events and places linked to the freedom struggle at the micro level of the district — People & Personalities, Events & Happenings, Hidden Treasures (Built & Natural Heritage), and Living Traditions & Art Forms.', '/images/media/sanskriti/digital-district-repository.jpg', 'https://culture.gov.in/digital-district-repository', 'Ministry of Culture · Sanskriti', 2),
  (4, 'Sansad Ki Kala', 'sansad-ki-kala', 'A celebration of India’s civilisational values, democratic ethos and artistic excellence as reflected in the new Parliament building — guardians, galleries such as Shilp Deergha, Sthapatya Deergha and Sangeet Deergha, signature installations and the Constitutional Gallery, curated by IGNCA.', '/images/media/sanskriti/sansad-ki-kala.png', 'https://culture.gov.in/sanskriti/sansad-ki-kala', 'Ministry of Culture · Sanskriti', 3),
  (5, 'Sengol', 'sengol', 'The Sengol — an august sceptre steeped in the spiritual and cultural traditions of ancient Tamil civilisation, symbolising the transfer of power from colonial rule to a sovereign Indian state when it was solemnly presented to Pandit Jawaharlal Nehru in 1947. Handcrafted by Vummidi Bangaru Chetty and sanctified by the seers of the Thiruvaduthurai Adheenam.', '/images/media/sanskriti/sengol.png', 'https://culture.gov.in/sanskriti/sengol', 'Ministry of Culture · Sanskriti', 4);
