  (2, 'ASK — Asia Society Korea Cultural Exchange', 'Ministry of Culture, Asia Society Korea', '2023', 'Biennial cultural exchanges of performing arts and exhibitions between India and Korea.', 'K-Pop-Kathak and Kalamkari convergences, artist residencies.', 'Asia Society Korea', NULL, 'https://www.indiaculture.gov.in', 'Partnership'),
