  (4, 'MoU with UNESCO for Conservation Capacity Building', 'Ministry of Culture, UNESCO New Delhi', '2023', 'Capacity building, technical assistance and documentation standards for World Heritage properties.', 'Workshops, site management training and emergency assistance protocols.', 'UNESCO', NULL, 'https://www.indiaculture.gov.in', 'International'),
  (5, 'MoU with National Museum for Research & Exhibition Exchange', 'Ministry of Culture, National Museum', '2024', 'Circulation of collections, joint research and visitor-data cooperation among national museums.', 'Loan exhibitions, travelling blocks and conservation clinics.', 'National Museum', NULL, 'https://www.nationalmuseumindia.gov.in', 'Museum'),
  (6, 'MoU with Sangeet Natak Akademi for Guru-Shishya Documentation', 'Ministry of Culture, SNA', '2021', 'Recording and archiving vanishing gharana traditions of music and dance.', 'Audiovisual archives, fellowship tracks and accreditation of gurus.', 'Sangeet Natak Akademi', NULL, 'https://sangeetnatak.gov.in', 'Academy');
