INSERT INTO "cities" ("id", "state_id", "name", "description", "history", "culture", "rituals", "handicrafts", "food", "iconic_battles", "latitude", "longitude", "image_url", "cultural_identity", "historical_overview", "arts_and_crafts", "festivals_and_rituals", "cuisine_and_languages", "important_personalities", "source_name", "source_url", "source_type", "last_verified_at") VALUES
  (1, 4, 'Guwahati', 'The gateway to the Northeast — an ancient city at the foot of the Kamakhya hills and the cultural capital of Assam.', 'From the ancient kingdom of Kamarupa through the Ahom-British eras, Guwahati has functioned as Assam''s pivotal seat of learning and sanctuated pilgrimage.', 'Bihu evenings on steep riverbanks, the Assamese theatre and film scene, and the colonial-era cotton college institutions.', 'Ambubachi Mela at Kamakhya, the Doul Jatra spring festival and riverine Makar Sankranti.', 'Muga silk weaving clusters, bell-metal (kanh) craft and bamboo workshops.', 'Masor tenga, pitha, duck curry and jolpaan sundries.', 'Saraighat''s naval battle legacy is remembered in riverfront memorials of the city.', 26.1445, 91.7362, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (2, 9, 'New Delhi', 'The national capital works through three historical cities: Shahjahanabad, British New Delhi and contemporary spectacle.', 'Founded by the British in 1911 to replace Calcutta as capital, built around the Raisina ridge over the seventh historical city of Delhi.', 'Government museums, the Mandi House performing arts hub, and the contemporary bazaars of Sarojini Nagar.', 'Beating Retreat at Vijay Chowk, the Republic Day parade on Kartavya Path.', 'Dilli Haat and Dastkar melas host the crafts of the whole nation.', 'Paranthe Wali Gali, Old Delhi kebabs, and the ''Bengali sweet'' corners of Chittaranjan park.', 'The Siege of Delhi (1857); the 3rd Battle of Panipat (1761) on Delhi''s doorstep.', 28.6139, 77.209, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (3, 11, 'Ahmedabad', 'A UNESCO-listed walled city and the mortar of the Mahatma''s ashram experiments.', 'Founded in 1411 by Sultan Ahmed Shah; the pol neighbourhoods and darwazas matured through three centuries of textile and craft wealth, then turned the pivot of Gandhi''s nationalism.', 'Dadi-communal pol life, the Navratri garba of the Manek Chowk laboratories and a heir-loomed museum scene.', 'Navratri raas at residence plinths and the Janmashthami dahi-handi festivals.', 'Patola silk, Bandhani, and the zari trade of western India.', 'Dhokla, Khaman, Fafda-Jalebi breakfast and thali of Undhiyu.', 'The 1411-era founding wars and the 1772 fall of Ahmedabad to the British.', 23.0225, 72.5714, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (4, 16, 'Bengaluru', 'The garden city and technology capital, layered over centuries of Kempegowda-era fort and cantonment life.', 'From a mud fort established by Kempegowda in 1537 through Mysuru wodeyar and colonial rule to today''s silicon plateau.', 'Kannada theatre and Hindustani music abounds; the Lalbagh and Cubbon garden institutions anchor civic culture.', 'Karaga festival of the Tigalars and the annual Ganesha chaturthi of the Basavanagudi quarter.', 'Sandalwood carving, silk weaving and silk-cotton machines of Doddaballapur.', 'Dosa, bisi bele bath, filter coffee of old Bengaluru and the garden-city vada-paav of its migrants.', 'The siege of Devanahalli where Tipu''s father Hyder Ali rose; the urbanising Bangalore of Tipu''s court.', 12.9716, 77.5946, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (5, 16, 'Mysuru', 'The palace city — a canvas of royal Wodeyar grandeur and the Dasara spectacle.', 'Under the Wodeyar and later British-adjacent rule, Mysuru became the emblematic centre of the modern royal state; the palaces and Dasara traditions are world-famous.', 'Mysuru painting and ivory-inlay workshops, the royal durbar Carnatic recitals and the daily illuminated palace show.', 'The nine-day Navaratri Dasara with the golden howda procession.', 'Mysuru silk, rosewood inlay, sandalwood and the sandal soap factories of the palace trust.', 'Mysuru masala dosa, Mysore Pak, and the royal chitterraj? san of the palace kitchens.', 'The 1799 Siege of Srirangapatna that ended Tipu''s rule.', 12.2958, 76.6394, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (6, 17, 'Kochi', 'The queen of the Arabian Sea — a layered port of Portuguese, Dutch, Jewish and Malayali cultures.', 'A spice-route emporium since antiquity, Kochi''s fortunes peaked under the Portuguese possession of 1503 and the later Dutch and British-era princely trades.', 'The Kochi-Muziris Biennale, kathakali repertories of Ernakulam and the harbourside folk performance circuit.', 'Onam bacchanal parades and the Cochin Carnival on New Year.', 'Coir goods, Chendum and Kathakali headgear workshops.', 'Kerala sadhya, karimeen pollichathu and toddy-shop cuisine.', 'The Portuguese-Dutch contest over Kochi (1663).', 9.9312, 76.2673, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (7, 21, 'Pune', 'Cultural capital of Maharashtra and the seat of the Peshwas. Pune is a living archive of Maratha history — wadas, forts on the horizon, classical music gharanas and a deep literary tradition.', 'Pune rose to prominence as the headquarters of the Peshwas of the Maratha confederacy in the 18th century. Educational and cultural movements of the 19th century — Deccan Education Society, Kesari press and women''s reform — made it a crucible of modern Indian thought.', 'Home of the Kirana and Gwalior gharanas of Hindustani classical music, the Bharat Natya Mandir, Sawai Gandharva festival and vibrant university theatre.', 'The elaborate ten-day Ganeshotsav, Bhimthadi jatra, and the Rathyatra on Bund Garden road.', 'Paithani sarees, Kolhapuri chappal trade hubs, and traditional jewellery clusters.', 'Puran poli, Misal pav, Mastani (a layered fruit-ice dessert), Bakarwadi and Vada pav.', 'The Battle of Sinhagad (1670) where Tanaji Malusare recaptured Kondhana fort; the frequent campaigns between the Marathas and the Mughals/Nizams across this region.', 18.5204, 73.8567, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (8, 21, 'Mumbai', 'India''s financial and cultural capital — a city of colonial-era gothic and art-deco architecture, a deep film and theatre culture, and one of the flagship museum ecosystems of the country.', 'Seven islands gifted to the East India Company in 1661 grew into the Bombay Presidency''s centre. The 19th century left a gothic revival skyline, while the 20th century made it the heart of Hindi cinema and the Bombay cultural renaissance.', 'The birthplace of Indian cinema (Dadasaheb Phalke), a hub of Marathi theatre, and a city of festivals from Ganeshotsav to the Kala Ghoda Arts Festival.', 'Ganeshotsav, Dahi Handi, Elephanta island annual fair and heritage walks of the Fort precinct.', 'Muharram taazia crafts, local lacquer and textile markets; gateway to Maharashtrian paithani trade.', 'Vada pav, Bhel puri, Batata vada, Kolhapuri thali, Parsi cafe cuisine and the Bombay sandwich.', 'The defence of Bombay during Anglo-Maratha conflicts; the naval and moundAnse engagements around the Bombay harbour.', 19.076, 72.8777, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (9, 29, 'Jaipur', 'The Pink City, a planned city of Rajput grandeur and the gateway to the fort chains of Amber, Nahargarh and Jaigarh.', 'Founded in 1727 by Sawai Jai Singh II, who built a rationally planned city inspired by Vastu. It later became a princely capital that merged martial Rajput traditions with scientific institutions like the Jantar Mantar observatory.', 'Rajput court etiquette, folk theatre, the Chand flowering of Hawa Mahal, and a thriving craft economy.', 'Gangaur processions, Teej celebrations and the annual Kite (Makar Sankranti) festival skies.', 'Blue pottery, block-printed textiles, gemstone cutting, Zardozi and lac bangles.', 'Dal baati churma, Pyaaz kachori, Ghewar and the canal-side sweet shops of Johari Bazar.', 'The 16th-17th century confrontations between Amber and the Mughals.', 26.9124, 75.7873, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (10, 31, 'Chennai', 'Tamil Nadu''s capital, a grid city of British-era institutions and the nerve centre of the Margazhi music season.', 'Founded around the Fort St. George settlement (1639); Chennai grew as the heart of the Madras Presidency and of the Tamil renaissance.', 'Carnatic music schools, Bharatanatyam institutions, the Madras film industry and the month-long December festival.', 'Pongal kolams, Dipavali early-morning oil baths and temple chariot festivals.', 'Kanchipuram silk, Kalamkari (Masulipatnam-inspired), shell crafts and bronze icons.', 'South Indian tiffin, Chettinad specials, filter coffee in the Mylapore coffee-house tradition.', 'The Anglo-French struggles for Madras (18th century); the Pallava defence of the region.', 13.0827, 80.2707, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (11, 31, 'Madurai', 'The temple city, organised around the four tanks of the Meenakshi Amman complex and a 2,500-year-old literary memory.', 'A Sangam-era capital of ancient Tamilakam; flourished under the Pandyas, Nayakas and later the British-adjacent Zamindari systems.', 'Temple processional culture, Tamil literature, and the energetic street food and jasmine markets.', 'Meenakshi Thirukalyanam, the ten-day Chithirai festival and tank-light ceremonies.', 'Tamil bronzes, malligai (jasmine) garlands and temple craft.', 'Madurai idli-kaapi mornings, mutton kari dosa, and the famous Jigarthanda cools.', 'The Nayaka struggles against the Sultanates and the later Anglo-Pandya clashes.', 9.9252, 78.1198, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (12, 34, 'Varanasi', 'The oldest living city on earth — 88 ghats, the Kashi Vishwanath temple and a weaving eternity of Banarasi silk.', 'A centre of learning over 3000 years; Mark Twain''s ''older than history''. Varanasi''s devotional rhythms and cultural firms have never stopped.', 'Ganga arti spectacles, the Benaras gharana sitar-singing, silk powerloom legacy and the sacred geography of the riverfront.', 'Evening Ganga aarti, dawn boat rituals, Dev Deepawali and the Ramnagar evenings.', 'Banarasi silk, wooden toy craft of Ramchhatra ghat and the zariwork of the city.', 'Kachori-jalebi of the temple lanes, laung-lata and the petha of the ghat side.', 'The 1194 siege of Varanasi by Qutb-ud-din Aibak; the 1775 transfer to the British.', 25.3176, 82.9739, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (13, 34, 'Lucknow', 'A nawabi city of grand imambaras, refined Chikankari and the melodious gharanas of Awadh.', 'Under the Nawabs of Awadh (18-19th c.), Lucknow matured into a capital of Indo-Mughal culture; 1857 made it the pivot of the uprising.', 'The Lucknow gharana of Hindustani music, Kathak of the Wajid Ali court, thumri and the exquisite chikankari embroidery.', 'Muharram processions of the Bara Imambara and the avadhipati festival of the autumn months.', 'Chikankari, Zardozi, clove-scented attars and the closed ''it-ar'' discipline of western UP.', 'Lucknowi biryani, Tunday kebab, basket chaat and the sharbat culture of royal courts.', 'The Siege of Lucknow (1857) — the longest defence of the Residency; the 1856 annexation.', 26.8467, 80.9462, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11'),
  (14, 36, 'Kolkata', 'The former capital of British India and the continuing cultural heart of Bengal — books, art, music and architecture.', 'A colonial trading town that became the seat of the Bengal Renaissance; the city gave the nation its first modern university, theatre and political movements.', 'The Durga Puja autumn carnival, Boi Mela, the Calcutta School of Art and a monumental heritage of Raj-era buildings.', 'Bondhon-rules of Durga Puja observance, Charak puja and the Rathyatra festival of Mahesh.', 'Kantha, shola pith idols, conch shell craft and Nakhoda-style Bangladeshi-influenced jewellery.', 'Phuchka, Kolkata kathi roll, mishti doi and the legendary ''sondesh'' confectioners.', 'The two ''battles of'' the colonial era (Plassey 1757, Buxar 1764).', 22.5726, 88.3639, '', NULL, NULL, NULL, NULL, NULL, NULL, 'Ministry of Culture (Prototype Seed)', 'https://www.indiaculture.gov.in', 'government_seed', '2026-09-11');
INSERT INTO "publications" ("id", "author_id", "title", "publisher", "year", "language", "subject", "isbn", "description", "institution", "catalogue_url", "digital_url") VALUES
  (1, NULL, 'The Discovery of India', 'Signet Press', '1946', 'English', 'History', '9780143031031', 'The great prose voyage through the Indic millennia written from Ahmednagar fort.', NULL, 'https://nationallibrary.gov.in', NULL),
  (2, 2, 'The Wonder That Was India', 'Sidgwick & Jackson', '1954', 'English', 'Indology', '9788120835935', 'The classic survey of ancient Indian society, religion and art.', NULL, 'https://nationallibrary.gov.in', NULL),
  (3, 3, 'Gitanjali (Song Offerings)', 'Indian Society of Letters', '1910', 'English/Bengali', 'Poetry', '9789387496765', 'The Nobel-winning lyrics of devotion and nature.', NULL, 'https://nationallibrary.gov.in', NULL),
  (4, 4, 'The Culture and Civilisation of Ancient India', 'Vikas', '1965', 'English', 'Indology', '9788122206261', 'A path-breaking materialist history of ancient India.', NULL, 'https://nationallibrary.gov.in', NULL),
  (5, 5, 'Ramayana (prose retelling)', 'Bharatiya Vidya Bhavan', '1950', 'English', 'Mythology', '9788172760265', 'The widely-read devotional retelling of Valmiki''s epic.', NULL, 'https://nationallibrary.gov.in', NULL),
  (6, 6, 'India: A History', 'HarperCollins', '2000', 'English', 'History', '9780002557177', 'A panoramic single-volume history from the Harappans to independence.', NULL, 'https://nationallibrary.gov.in', NULL),
  (7, 5, 'Mahabharata (prose retelling)', 'Bharatiya Vidya Bhavan', '1951', 'English', 'Mythology', '9788172763563', 'The compelling prose adaptation of the great epic.', NULL, 'https://nationallibrary.gov.in', NULL),
  (8, 8, 'The Struggle for Freedom in Sanskrit Drama', 'Madras University', '1969', 'English', 'Sanskrit', NULL, 'A specialist work on social reform in classical Sanskrit drama.', NULL, 'https://nationallibrary.gov.in', NULL),
  (9, 1, 'Bharatnama', 'Jawaharlal Nehru Memorial Fund', '2007', 'Hindi', 'History', NULL, 'Hindi compilation of the Discovery of India excerpts.', NULL, 'https://nationallibrary.gov.in', NULL),
  (10, 7, 'The Village of the Heart: Folk Tales of Tamil Nadu', 'NBT', '1983', 'English', 'Folklore', NULL, 'Household tales carrying the living heritage of Tamil Nadu.', NULL, 'https://nationallibrary.gov.in', NULL);
INSERT INTO "heritage_sites" ("id", "city_id", "state_id", "name", "category", "description", "history", "location", "latitude", "longitude", "historical_period", "architecture", "significance", "famous_people", "related_events", "image_url", "featured", "slug", "heritage_type", "region", "unesco_status", "unesco_year", "unesco_category", "google_360_url", "main_image", "established", "created_at", "updated_at") VALUES
  (1, 1, 4, 'Kamakhya Temple', 'Temple', 'One of the foremost Shakti shrines, famed for the Ambubachi fertility festival and its beehive-shaped dome.', 'The goddess Kamakhya site is present on the Nilachal hill since antiquity, rebuilt in the 17th century and continuously patronised by the Ahom kings.', 'Nilachal Hill', 26.1445, 91.7362, '8th century (rebuilt 17th)', 'Nilachal-type temple with a beehive shikhara and sculptured panels of the Dasamahavidya.', 'The central shrine of Tantric Shaktism in India and a keeper of Assamese temple tradition.', 'Naraka (mythic), Ahom king Siva Singha (patron)', 'Ambubachi Mela (June) — among India''s largest fairs.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (2, 1, 4, 'Umananda Temple', 'Temple', 'A small Shiva temple on the world''s smallest inhabited river island.', 'Built in 1694 by the Ahom king Gadadhar Singha; pilgrims cross the Brahmaputra to the island, now a protected heritage precinct.', 'Peacock Island, Brahmaputra', 26.1445, 91.7362, '1694', 'Nilachal-style shikhara with stone carvings of Surya and Ganesha.', 'A unique riverine sacred island, administratively protected along with the golden langur sanctuary.', 'Gadadhar Singha', 'Mahashivratri all-night festival.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (3, 1, 4, 'Srimanta Sankardev Kalakshetra', 'Cultural', 'The premier cultural institution of the Northeast, preserving Sattriya performance and Assamese crafts.', 'Established in 1998 to honour the Vaishnavite saint-poet Sankardeva; museum and performance spaces are run under government recognisation.', 'Panjabari, Guwahati', 26.1445, 91.7362, '1998 (museum complex)', 'Modern multi-gallery museum with a meditation lake and ethnographic pavilions.', 'An open-air museum that anchors the ministry''s heritage programme in the region.', 'Srimanta Sankardeva, Madhavdeva', 'Sankardeva Jayanti and the annual Assamese craft fair.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (4, 2, 9, 'Red Fort', 'Fort', 'The Mughal imperial citadel of Shah Jahan and the national venue of Independence Day.', 'Completed in 1648 as the palace-fort of Shahjahanabad, the fort became the hallmark of Mughal ''repaired'' power until 1857, after which British usage began.', 'Old Delhi', 28.6139, 77.209, '1648', 'Red sandstone walls 2.5 km; Diwan-i-Aam, Diwan-i-Khas (with the Peacock Throne history) and the Rang Mahal.', 'UNESCO World Heritage; the Prime Minister addresses the nation here on 15 August each year.', 'Shah Jahan, Aurangzeb, Emperor Bahadur Shah Zafar', 'Independence Day; light-and-sound retrofit.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (5, 2, 9, 'Qutub Minar', 'Monument', 'The 12th-century victory tower and the surrounding Quwwat-ul-Islam mosque complex of Delhi''s first Sultanate.', 'Begun by Qutb-ud-din Aibak in 1192-1200 and completed by successor sultans; the Iron Pillar of Chandra dates centuries earlier.', 'Mehrauli', 28.6139, 77.209, '12th century', '73-metre fluted tower of sandstone and marble with Quran inscriptions.', 'UNESCO heritage and the anchor of the Mehrauli archaeological park.', 'Qutb-ud-din Aibak, Iltutmish, Ala-ud-din Khalji', 'Monument week sound shows.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (6, 2, 9, 'Humayun''s Tomb', 'Monument', 'The first great garden-tomb of the Mughals — the prototype of the Taj.', 'Commissioned by Empress Bega Begum around 1569-70 for Emperor Humayun; its chahar-bagh and double dome set the template of Mughal architecture.', 'Nizamuddin East', 28.6139, 77.209, '1570', 'Squat-on-dome garden tomb with red sandstone and white marble accents.', 'UNESCO World Heritage; a restored exemplar of the Aga Khan-ASI partnership.', 'Humayun, Bega Begum, Dara Shukoh (later burials)', 'Heritage walks during Delhi art weeks.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (7, 3, 11, 'Sabarmati Ashram', 'Monument', 'Mahatma Gandhi''s home for the 1917-30 satyagraha years, now a national museum of the freedom movement.', 'Established 1917; the famous Dandi salt march began here in 1930. Following the Mahatma''s assassination, the ashram was donated to the nation and is preserved by the Gandhi Smarak Sangrahalaya.', 'Sabarmati riverbank', 23.0225, 72.5714, '1917', 'Clusters of simple Gujarat tiles, earth-coloured kampus (huts) with a quotidian museum.', 'One of the ministry''s key Gandhi heritage sites along with the Hridaya Kunj.', 'Mahatma Gandhi, Kasturba Gandhi, Mirabehn', '2 October commemorations and the Dandi-pun ceremony.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (8, 3, 11, 'Bhadra Fort', 'Fort', 'The Sultanate-era citadel of Ahmedabad with its Teen Darwaza gate and the Jhulta Minar-bridging clock tower complex.', 'The original citadel of Ahmedabad begun in 1411; layered by Mughal and Maratha re-interiorations, showcasing the survival of civic history into the present-day city.', 'Ahmedabad', 23.0225, 72.5714, '1411', 'Fortified red-sandstone walls, royal durbar halls and connected gardens.', 'An urban fort that anchors the UNESCO walled-city status.', 'Ahmed Shah I', 'Walled-city heritage walks begin at Teen Darwaza.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (9, 4, 16, 'Bangalore Palace & Fort precinct', 'Monument', 'A Tudor-style palace of the Wodeyars with the surviving 16th-century Kempegowda fort gate nearby.', 'The Kempegowda mud fort (1537) preceded the occupier''s armies; the palace, completed 1878, was modelled on Windsor Castle and remains a living royal museum.', 'Bengaluru', 12.9716, 77.5946, '1878 (fort 1537)', 'Tudor-Gothic turrets, wood carvings and Belgian glass interiors.', 'The most-visited private palace of South India, now a heritage venue at the heart of the IT capital.', 'Kempegowda, Wodeyar dynasty', 'Music concerts within the palace courtyards.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (10, 4, 16, 'Tipu Sultan''s Summer Palace', 'Palace', 'The teak-columned ''Abode of Happiness'' of Tipu Sultan, now a heritage museum of the Anglo-Mysore wars.', 'Built as Tipu''s summer palace in teak and plaster typically between 1781-91; it later served as the British Residency and post-Independence as the government office.', 'Bengaluru', 12.9716, 77.5946, '1791', 'Two-storey teak columns, frescoed floral arches and balconies around a rectangular court.', 'A centrally protected monument narrating the Mysuru Sultanate.', 'Tipu Sultan, Hyder Ali', 'The annual Tipu Jayanti and heritage-week tours.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (11, 5, 16, 'Mysuru Palace', 'Monument', 'The resplendent IndoSaracenic seat of the Wodeyars and India''s most-visited monument.', 'The present palace, completed 1912 after a fire, inherits the site of the old wooden palace. It remains the official residence of the royal family and the Dasara stage.', 'Mysuru', 12.2958, 76.6394, '1912 (current form)', 'Indo-Saracenic dome extravaganza, colonnaded durbar halls and intricately carved doors.', 'The economic and emotional engine of Mysuru heritage tourism; a state-protected icon.', 'Wodeyar dynasty, Henry Irwin (architect)', 'Mysuru Dasara procession and nightly illumination.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (12, 5, 16, 'Chamundi Hill Temples', 'Temple', 'The hill of the royal goddess Chamundeshwari with the iconic Nandi statue of the 17th century.', 'The temple on the hill (panoramically called the ''weather gate of Mysuru'') was patronised by the Wodeyars as the family deity''s abode.', 'Mysuru outskirts', 12.2958, 76.6394, '17th century', 'Dravidian gopurams, the monolithic 5-metre Nandi carved in 1659, and a 1000-step stairway.', 'A devotional summit framing the Mysuru skyline.', 'Wodeyar kings', 'Dasara festivals at the hill shrine.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (13, 6, 17, 'Fort Kochi', 'Monument', 'The historic quarter of European colonial architecture — the Fort, Chinese fishing nets, Santa Cruz Basilica and Paradesi Synagogue.', 'The Portuguese set up India''s first European fort-town here in 1503; the Dutch wrested it in 1663 and the British continued its cosmopolitan growth.', 'Kochi waterfront', 9.9312, 76.2673, '1503', 'Dutch/Portuguese gabled houses, cashew fort walls and the St. Francis church corridor.', 'A rare waterfront colonial ensemble protected with the entire Fort Kochi heritage zone.', 'Vasco da Gama (buried here, 1524)', 'Kochi-Muziris Biennale installations across the quarter.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (14, 6, 17, 'Mattancherry Palace', 'Palace', 'The ''Dutch Palace'' gifted by the Portuguese to the Raja of Cochin, famed for Ramayana murals.', 'Built circa 1555 and renovated by the Dutch in the 17th century; the palace museum opened in 1985 under state archaeology.', 'Mattancherry', 9.9312, 76.2673, '1555', 'Nālukettu-style Kerala palace with carved teak ceilings and wall-to-wall murals.', 'Keeper of the most complete series of Kerala mural art.', 'Raja of Cochin; Dutch patrons', 'Mural conservation workshops.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (15, 6, 17, 'Santa Cruz Basilica & Paradesi Synagogue', 'Monument', 'Twin monuments of Kochi''s plural heritage — the painted cathedral and the oldest Jewish synagogue of the Commonwealth.', 'The basilica, first laid in 1505, was elevated as cathedral by the Portuguese; the synagogue''s congregation traces to the ''White Jews'' of the Malabar coast.', 'Fort Kochi / Mattancherry', 9.9312, 76.2673, '1505 (synagogue 1568)', 'Hand-painted interior of the basilica; Chinese-tile floors and brass-railed artwork of the synagogue.', 'Evidence of the deepest Jewish-Christian-Sharing coexistence heritage of Indian shores.', 'Portuguese bishopry, the Cochini community', 'Onam concerts in the synagogue courtyard.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (16, 7, 21, 'Shaniwar Wada', 'Monument', 'The fortified residence of the Peshwas and the political centre of the Maratha confederacy for a century.', 'Built by Peshwa Baji Rao I in 1732 on the rights of the Fadnis family. The palace witnessed the golden era of the Peshwas, the chilling legend of young Naro Peshwa (phantom cries), and later the great fire of 1828 that destroyed much of the structure.', 'Kasba Peth', 18.5204, 73.8567, '1732', 'A 21-metre-tall five-storey palace with teak pillars, lime-and-brick walls and the famous Dilli Darwaza; only parts of the bastion and fountains survive.', 'Symbol of Maratha power and the heart of Pune''s Peshwa-era narrative; prime ministry-protected heritage asset.', 'Peshwa Baji Rao I, Nanasaheb Peshwa, Madhavrao Peshwa, Nana Phadnavis', 'Ganeshotsav inaugurations historically addressed from here; the 1828 fire.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (17, 7, 21, 'Sinhagad Fort', 'Fort', 'Ancient hill fort that marks the legendary victory of Tanaji Malusare over the Mughal garrison.', 'Formerly Kondhana, the fort changed hands between Yadavas, Mughals and Marathas. It became immortal through the 1670 battle in which Tanaji Malusare captured it and gave his life — prompting Shivaji''s tribute, ''gad aala, pan sinha gela''.', '25 km SW of Pune', 18.5204, 73.8567, '11th century', '1700-feet hill fortress with bastions, gates and the iconic Tanaji samadhi and a memorial.', 'A living site of Maratha military heritage and now a city-near weekend heritage zone visited by lakhs.', 'Chhatrapati Shivaji Maharaj, Tanaji Malusare, Raiba', 'Sinhagad battle anniversary commemorations; monsoon treks by heritage groups.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (18, 7, 21, 'Aga Khan Palace', 'Monument', 'An elegant edifice famous as a national memorial to Mahatma Gandhi and the Quit India internees.', 'Built by Sultan Aga Khan III as a charity palace. During 1942-44 it served as a prison for Mahatma Gandhi, Kasturba (who died here) and Mahadev Desai. Kasturba''s and Desai''s samadhis lie within the grounds.', 'Yerawada, Pune', 18.5204, 73.8567, '1892', 'A grand Italian-style colonnaded building set in 19 acres of lawns, regarded as the finest Poona palace of its era.', 'A site of national importance under the Gandhi Heritage and preservation network of the Ministry of Culture.', 'Mahatma Gandhi, Kasturba Gandhi, Mahadev Desai, Sarojini Naidu', 'Quit India movement history; Gandhi Jayanti commemorations.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (19, 7, 21, 'Raja Dinkar Kelkar Museum', 'Museum', 'A singular museum of everyday material culture — palanquins, musical instruments, nutcrackers and lamps.', 'Founded by Dinkar Kelkar, who spent decades personally collecting objects; the museum was donated to the Government of Maharashtra and is a celebrated repository of Indian craftsmanship.', 'Natu Baug, Shukravar Peth', 18.5204, 73.8567, '1970s collection', 'Three floors of curated galleries around the famous Mastani Mahal hall.', 'Bridges documented heritage of decorative arts for researchers and students.', 'Raja Dinkar Kelkar', 'Museum lecture series and heritage walks organised by the museum society.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (20, 7, 21, 'Vishrambaug Wada', 'Monument', 'The elegant wada of Peshwa Baji Rao II, later a venue for dramatic and musical performances.', 'Built in 1807 as the chief residence of Peshwa Baji Rao II, the wada hosted Maratha court gatherings and was part of ''Sharavan Peth'' cultural life before becoming a post office and municipal space.', 'Narayan Peth', 18.5204, 73.8567, '1807', 'A two-storey wada with intricately carved wooden balconies and an oil-painted central bust of the Peshwa.', 'An important Peshwa-era urban heritage structure in the heart of the old city.', 'Peshwa Baji Rao II', 'Old Pune heritage walks.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (21, 8, 21, 'Gateway of India', 'Monument', 'The iconic basalt arch on the Mumbai waterfront commemorating the visit of King George V and Queen Mary.', 'Unveiled in 1924 in Indo-Saracenic style; the last British troops departed through it in 1948. It anchors the city''s ceremonial and tourist identity.', 'Apollo Bunder', 19.076, 72.8777, '1924', 'Basalt and reinforced concrete Indo-Saracenic arch, 26 metres high.', 'One of the most photographed national landmarks; an ASI-protected monument.', 'George Wittet (architect), Lord Sydenham', 'Public gatherings, heritage walks and the annual Kala Ghoda festival fringe.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (22, 8, 21, 'Chhatrapati Shivaji Maharaj Terminus', 'Monument', 'A UNESCO World Heritage railway terminus and the finest example of Victorian Gothic Revival in India.', 'Designed by F.W. Stevens and completed in 1887 to commemorate Queen Victoria''s golden jubilee; renamed after the Maratha warrior king in 1996.', 'Fort, Mumbai', 19.076, 72.8777, '1887', 'Gothic Revival with Indian ornament — pointed arches, stained glass, and a dramatic central dome.', 'UNESCO-listed; a living monument still functioning as one of India''s busiest railway stations.', 'F.W. Stevens, Axel Haig (illustrator)', 'UNESCO heritage walks during museum week.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (23, 8, 21, 'Elephanta Caves', 'Archaeological', 'Rock-cut cave temples dedicated to Shiva, celebrated for the monumental trimurti sculpture.', 'Cut into basalt rock during the Kalachuri-Rashtrakuta era; the caves were documented as a World Heritage Site in 1987.', 'Elephanta Island', 19.076, 72.8777, '5th–8th century', 'Five hypostyle cave complexes with colossal panels of Shiva as Nataraja, Ardhanarishvara and the three-faced Trimurti.', 'Masterpiece of Indian rock-cut art; managed by the Archaeological Survey of India.', '— (anon rock-cut master carvers)', 'Annual Elephanta island festival dance performances.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (24, 8, 21, 'Dr. Bhau Daji Lad Mumbai City Museum', 'Museum', 'Mumbai''s oldest surviving museum, a treasure house of the city''s 19th century decorative arts.', 'Opened in 1872 as the Victoria and Albert Museum, Bombay; extensively restored and reopened as the Bhau Daji Lad Museum in 2008.', 'Byculla East', 19.076, 72.8777, '1872', 'Palladian-style building listed as a Grade I heritage structure.', 'Flagship city museum preserving clay crafts, school art and archives (an ASI-grade protected building).', 'George Birdwood (curator) and 20th-century art patrons', 'Public programming on Mumbai heritage and museum week showcases.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (25, 9, 29, 'Amber Fort', 'Fort', 'Mughal-art-and-Rajput-styled hill fort, once the capital of the Kachwaha rulers.', 'Constructed from 1592 under Raja Man Singh I and expanded over a century; the palace complex blends the Diwan-i-Aam, Sheesh Mahal and the Laxmi sun temple pictures.', 'Amer, Jaipur', 26.9124, 75.7873, '1592', 'Hindu-Rajput + Mughal synthesis with mirror mosaic (Sheesh Mahal), lattice screens and terraced gardens.', 'A UNESCO World Heritage ''Hill Forts of Rajasthan'' property and pilgrimage of Rajput architecture.', 'Raja Man Singh I, Mirza Raja Jai Singh', 'Sound-and-light show; teej celebrations.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (26, 9, 29, 'Hawa Mahal', 'Monument', 'The five-storey ''Palace of Winds'' with 953 jharokha windows, made so the royal ladies could watch street processions unseen.', 'Built by Maharaja Sawai Pratap Singh in 1799 as an extension of the City Palace women''s quarters.', 'Badi Choupad, Jaipur', 26.9124, 75.7873, '1799', 'Pyramidal honeycomb of 953 small windows; the pink sandstone facade is one of India''s most famous vistas.', 'The symbol of Jaipur''s skyline and a masterpiece of latticed architecture.', 'Sawai Pratap Singh; Lal Chand Ustad (architect)', 'Photographic heritage trails of the Pink City.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (27, 9, 29, 'Jantar Mantar', 'Monument', 'The largest of Jai Singh II''s astronomical observatories — a stone sundial and instrument park.', 'Built in 1728 and still functioning as a calibrating instrument for time and stars.', 'City Palace Road', 26.9124, 75.7873, '1728', 'Nineteen masonry instruments including the giant Samrat Yantra sundial, 27 metres high.', 'UNESCO World Heritage site; a rare fusion of science and monumental architecture.', 'Sawai Jai Singh II', 'Astronomy outreach on national science days.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (28, 9, 29, 'City Palace', 'Monument', 'The still-royal palace complex of Jaipur with courtyards, museums and the Chandra Mahal.', 'Begun under Jai Singh II and enlarged by later rulers; the palace museum was opened in 1959, displaying textiles and royal carriages.', 'Jaipur', 26.9124, 75.7873, '18th century', 'Rajput-Mughal court architecture with pillared pavilions, painted gateways and the Pran Prasad interior.', 'Dual life as ceremonial seat of the Jaipur royal family and a principal museum.', 'Jaipur royal family', 'Museum season programmes and craft exhibitions.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (29, 10, 31, 'Fort St. George', 'Monument', 'The first British fortress in India, containing the Fort Museum and St. Mary''s Church.', 'Established in 1644 as the East India Company''s foothold, it grew into the Madras Presidency capital and later the Indian Administrative Service''s roots.', 'Chennai', 13.0827, 80.2707, '1644', 'Bastioned coastal fort with English and Mughal-era interiors.', 'An origin point of British India administration and a continuous museum since 1948.', 'Elihu Yale, Robert Clive, Raja Sir Ramaswami Mudaliar', 'Independence day exhibitions and heritage tours.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (30, 10, 31, 'Kapaleeshwarar Temple', 'Temple', 'The great Shiva shrine of Mylapore with its towering gopuram, rebuilt in the Vijayanagara idiom.', 'The cult site of the goddess Karpagambal has traditions going back to the Pallava period; the present structure dates to the 16th century.', 'Mylapore', 13.0827, 80.2707, '7th–17th century', 'Dravidian gopuram with tiered sculptures over a tank and mandapa court.', 'A living centre of Tamil temple culture and the Arubathimoovar procession.', 'Hindu saint Arunagirinathar (association)', 'Arubathimoovar festival and daily agamic worship.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (31, 10, 31, 'Santhome Cathedral & Marina heritage precinct', 'Monument', 'A neo-gothic cathedral on the reputed tomb site of St. Thomas, anchoring the Chennai coastal heritage drive.', 'The Portuguese founded a cathedral in 1523; the towering basilica was rebuilt in 1896 and elevated by the Church.', 'Chennai coast', 13.0827, 80.2707, '16th century (present structure 1896)', 'Painted neo-gothic cathedral with stained glass and a 55-metre tower.', 'One of India''s major basilicas and a coastal landmark along the heritage ''Chennai shoreline''. ', 'Frei. Scientists supported marine vocation', 'Feast of St. Thomas, December flame mitigations.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (32, 11, 31, 'Meenakshi Amman Temple', 'Temple', 'A vast Dravidian temple-city of 14 gopurams, a gold-plated sanctum and the thousand-pillar mandapam.', 'The local shrine of the fish-eyed goddess Meenakshi was greatly expanded by the Nayakas in the 16th-17th centuries; it embodies the Tamil concept of temple-cosmos.', 'Madurai city centre', 9.9252, 78.1198, '17th century (older origins)', '14 towered gopurams over a 14-acre precinct; the thousand-pillar hall (Meenakshi Nayakar mandapam) with life-size yali figures.', 'One of India''s most frequented pilgrimage and iconography sites, and a museological source of stone sculpture.', 'Nayaka kings Vishwanatha and Thirumalai', 'Chithirai festival and daily cosmic processions.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (33, 11, 31, 'Thirumalai Nayakkar Mahal', 'Palace', 'Indo-Saracenic palace of the Nayaka ruler, partly ruined, partly restored into a museum and sound-and-light venue.', 'Built by King Thirumalai Nayak in 1636 and once a vast 13-acre court complex; destroyed partially by his grandson before restoration under the British.', 'Madurai', 9.9252, 78.1198, '1636', 'Stucco arches, carved pillars and the 2-metre-diameter central courtyard dome.', 'Demonstrates the fusion of Dravidian and Islamic architecture and the royal patronage of arts.', 'Thirumalai Nayak, Rani Mangammal', 'Sound-and-light show evenings; classical recitals.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (34, 12, 34, 'Kashi Vishwanath Temple', 'Temple', 'The supreme Shiva shrine of the holy city, restored across centuries and now enhanced by the Kashi Vishwanath corridor.', 'The current temple dates to 1776-1780 added by Ahilyabai Holkar; with the 2021 corridor it has re-opened the sacred link between the temple and the Ganga ghats.', 'Vishwanath Gali', 25.3176, 82.9739, '1780 (present structure)', 'Golden-plated spire over a dense Kashi-bearing quadrangle.', 'One of the twelve jyotirlingas and the emotional summit of Hindu pilgrimage.', 'Ahilyabai Holkar; Adi Shankaracharya (association)', 'Maha Shivratri and the daily arti processions.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (35, 12, 34, 'Sarnath', 'Archaeological', 'Where the Buddha delivered his first sermon — with the Dhamek Stupa and the great Ashokan lion-capital heritage.', 'The Deer Park of Isipatana where the Buddha preached the first turning of the wheel of dharma; later expanded under Ashoka with stupas and monasteries.', '10 km from Varanasi', 25.3176, 82.9739, '3rd century BCE', 'The Dhamek stupa with geometric drum-carving and the Ashokan lion capital pillar base.', 'The most sacred Buddhist archaeological site of India, administered by the ASI.', 'Gautama Buddha, Emperor Ashoka', 'Buddha Purnima congregations and the annual Sarnath heritage evening.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (36, 12, 34, 'Dashashwamedh Ghat & riverfront', 'Monument', 'The grandest of Varanasi''s 88 ghats and the stage of the eternal Ganga aarti.', 'The riverfront steps, repaired under many rulers, have staged cremation-bound ghat life and the cadence of aarti for centuries.', 'Ganga riverfront', 25.3176, 82.9739, 'Ancient', 'Wide stone terraces of steps flattening into the Ganga.', 'The choreography of Kashi''s public devotional culture with UNESCO intangible-heritage links.', '—', 'Daily aarti; Dev Deepawali grand lamp processions.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (37, 13, 34, 'Bara Imambara', 'Monument', 'The colossal hall of Asaf-ud-Daula with the legendary bhool-bhulaiya labyrinth and the Roof labyrinth of Nawabi architecture.', 'Built 1784-1791 as a famine relief work by Nawab Asaf-ud-Daula, the Imambara was meant to outlast his rule — and still stands.', 'Lucknow', 26.8467, 80.9462, '1784', 'One of the largest vaulted galleries in the world with 26-metre span and the famous maze.', 'The Great Imambara district is the keystone of Lucknow''s heritage zone.', 'Nawab Asaf-ud-Daula', 'Muharram processions and the annual exhibition of awadhica.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (38, 13, 34, 'Bara Rumi Darwaza', 'Monument', 'The towering gateway of the old city, modelled on a Constantinople portal.', 'Part of the Asafi creation of the late 18th century; the 60-foot archway greets all processions to the Great Imambara.', 'Lucknow', 26.8467, 80.9462, 'c. 1784', 'A huge square plan with an ogive arch and kiosk, all of brick and plaster.', 'Symbol of Lucknow''s architectural horizon.', 'Nawab Asaf-ud-Daula', 'Marriage-season processions.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (39, 13, 34, 'Chhota Imambara', 'Monument', 'The glittering palace of lamps — the Husainabad Imambara built by Muhammad Ali Shah.', 'Built in 1838 as his mausoleum, it blazes with dangling chandeliers during celebrations.', 'Lucknow', 26.8467, 80.9462, '1838', 'Golden-topped gateways and coloured-glass interiors surrounding a central court.', 'A gilded masterwork adjacent to the watch-tower of Hussainabad.', 'Muhammad Ali Shah (Nawab of Awadh)', 'Husainabad lighting at Mild.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (40, 14, 36, 'Victoria Memorial', 'Monument', 'A white-marble memorial to Queen Victoria that houses one of India''s great museums of colonial and Indian history.', 'Conceived by Lord Curzon, completed in 1921; today''s Victoria Memorial Hall is a museum of the Raj and modern Kolkata.', 'Maidan, Kolkata', 22.5726, 88.3639, '1921', 'Indo-Saracenic revival Italianate dome in Makrana marble with attached gardens and statue gallery.', 'A landmark preserve of the Indian national movement in visual form (the Durbar and pictorial galleries).', 'Lord Curzon; Queen Victoria (honoured)', 'The museum''s annual exhibitions coincide with heritage week in January.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (41, 14, 36, 'Indian Museum, Kolkata', 'Museum', 'The oldest and largest multipurpose museum in the Asia-Pacific region, cataloguing archaeology, natural history and art.', 'Founded in 1814 by the Asiatic Society; the present Palladian building dates from 1875. Its collections from Bharhut and Mohenjodaro anchor South Asian archaeology.', 'Chowringhee', 22.5726, 88.3639, '1814', 'Classical-revival building with a verandah around a courtyard and colonnaded galleries.', 'The single most valuable public museum for Indian antiquities and the inspiration for the ministry''s museum programme.', 'Sir Stamford Raffles (patron), William Jones (Asiatic Society founder)', 'International Museum Day programmes and the annual heritage lecture series.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (42, 14, 36, 'Belur Math', 'Monument', 'The spiritual centre of the Ramakrishna order, an architectural synthesis of all Indian religions.', 'Consecrated in 1938 under Swami Vivekananda''s design vision; the shrine complex symbolises Hindu, Muslim and Christian forms in one structure.', 'Hooghly bank', 22.5726, 88.3639, '1938', 'The blend of temple, mosque, church and monastery in a single dome; river-facing facade.', 'A modern monument of India''s spiritual renewal and a place of heritage-led spiritual tourism.', 'Swami Vivekananda, Sarada Devi, Sri Ramakrishna', 'Sri Ramakrishna''s birth anniversary processions; Navaratri spiritual retreats.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
