  (72, NULL, NULL, 'Red Fort', 'man-made', 'The great Mughal citadel palace of Shah Jahan, built of red sandstone along the Yamuna.', 'Ordered by Shah Jahan in 1638 and completed in 1648, the fort was the residence of the Mughal emperors for nearly two centuries. India''s Independence Day flag is raised here every year since 1947.', 'Delhi', 28.6562, 77.241, 'Mughal, 17th century', NULL, 'UNESCO World Heritage Site (2007) and the symbolic heart of modern India''s freedom narrative.', NULL, NULL, '/images/trending/red-fort.jpg', 0, 'red-fort', 'tangible', 'Delhi', 'WORLD', '2007', NULL, 'https://www.google.com/maps?layer=c&cbll=28.6562,77.241&cbp=11,0,0,0,0', '/images/trending/red-fort.jpg', '1648', '2026-09-08', '2026-09-08'),
  (73, NULL, NULL, 'Taj Mahal', 'man-made', 'The ivory-white marble mausoleum built by Emperor Shah Jahan in memory of Mumtaz Mahal.', 'Commissioned in 1632 and completed around 1653, the Taj Mahal is celebrated for its perfect symmetry, pietra dura inlay and changeless white marble that shifts colour through the day.', 'Agra, Uttar Pradesh', 27.1751, 78.0421, 'Mughal, 17th century', NULL, 'One of the New Seven Wonders of the World and the foremost UNESCO World Heritage Site of India (1983).', NULL, NULL, '/images/heritage/taj-mahal.jpg', 0, 'taj-mahal', 'tangible', 'Agra, Uttar Pradesh', 'WORLD', '1983', NULL, 'https://www.google.com/maps?layer=c&cbll=27.1751,78.0421&cbp=11,0,0,0,0', '/images/heritage/taj-mahal.jpg', '1648', '2026-09-08', '2026-09-08'),
  (74, NULL, NULL, 'Amber Fort', 'man-made', 'The majestic hilltop palace-fort of the Kachhwaha rulers above Maota Lake.', 'Construction began under Raja Man Singh I in 1592 on the earlier Amber stronghold and continued under successive rulers, blending Rajput and Mughal architecture.', 'Amer, Jaipur, Rajasthan', 26.9855, 75.8513, 'Rajput–Mughal, 16th century', NULL, 'A masterpiece of Rajput palace architecture and part of the UNESCO Hill Forts of Rajasthan (2013).', NULL, NULL, '/images/heritage/amber-fort.jpg', 0, 'amber-fort', 'tangible', 'Amer, Jaipur, Rajasthan', 'WORLD', '2013', NULL, 'https://www.google.com/maps?layer=c&cbll=26.9855,75.8513&cbp=11,0,0,0,0', '/images/heritage/amber-fort.jpg', '1592', '2026-09-08', '2026-09-08'),
  (75, NULL, NULL, 'Hampi — Group of Monuments', 'man-made', 'The ruined capital of the Vijayanagara Empire, a vast open-air museum by the Tungabhadra.', 'Hampi flourished from the 14th century as the seat of the Vijayanagara empire until its fall in 1565. The Virupaksha temple, stone chariot and elephant stables survive among boulder-strewn landscapes.', 'Hampi, Karnataka', 15.335, 76.46, 'Vijayanagara, 14th–16th century', NULL, 'UNESCO World Heritage Site (1986) and the country''s largest living heritage site.', NULL, NULL, '/images/heritage/hampi.jpg', 0, 'hampi', 'tangible', 'Hampi, Karnataka', 'WORLD', '1986', NULL, 'https://www.google.com/maps?layer=c&cbll=15.335,76.46&cbp=11,0,0,0,0', '/images/heritage/hampi.jpg', '14th century', '2026-09-08', '2026-09-08'),
  (76, NULL, NULL, 'Ellora Caves', 'man-made', 'Thirty-four rock-cut cave temples and monasteries spanning Buddhist, Hindu and Jain faiths.', 'Carved between the 6th and 10th centuries CE, the Kailasa temple in Court 16 is a single colossal rock-cut monument representing the culmination of Indian rock-cut architecture.', 'Aurangabad, Maharashtra', 20.0268, 75.1771, 'Rashtrakuta, 6th–10th century CE', NULL, 'UNESCO World Heritage Site (1983), celebrated for religious harmony in stone.', NULL, NULL, '/images/heritage/ellora.jpg', 0, 'ellora-caves', 'tangible', 'Maharashtra', 'WORLD', '1983', 'Cultural', 'https://www.google.com/maps?layer=c&cbll=20.0268,75.1771&cbp=11,0,0,0,0', '/images/heritage/ellora.jpg', '6th century CE', '2026-09-08', '2026-09-08'),
  (77, NULL, NULL, 'Ajanta Caves', 'man-made', 'Buddhist rock-cut caves famous for murals and sculpture of the Gupta age.', 'Excavated in two phases (2nd century BCE and 5th–6th century CE), the 30 caves preserve some of the finest surviving paintings of ancient India, recounting the Jataka tales.', 'Aurangabad, Maharashtra', 20.5519, 75.7005, 'Satavahana–Vakataka, 2nd c. BCE–6th c. CE', NULL, 'UNESCO World Heritage Site (1983), the pinnacle of Indian mural painting.', NULL, NULL, '/images/heritage/ajanta.jpg', 0, 'ajanta-caves', 'tangible', 'Maharashtra', 'WORLD', '1983', 'Cultural', 'https://www.google.com/maps?layer=c&cbll=20.5519,75.7005&cbp=11,0,0,0,0', '/images/heritage/ajanta.jpg', '2nd century BCE', '2026-09-08', '2026-09-08'),
  (78, NULL, NULL, 'Fatehpur Sikri', 'man-made', 'Akbar''s short-lived red-sandstone imperial capital, later abandoned for lack of water.', 'Built between 1571 and 1585, the city honoured the Sufi saint Salim Chishti. Its Buland Darwaza and marble-clad mausoleum survive as architectural masterpieces.', 'Agra district, Uttar Pradesh', 27.091, 77.6612, 'Mughal, 16th century', NULL, 'UNESCO World Heritage Site (1986) — a unified expression of Indo-Islamic civic planning.', NULL, NULL, '/images/heritage/fatehpur-sikri.jpg', 0, 'fatehpur-sikri', 'tangible', 'Agra district, Uttar Pradesh', 'WORLD', '1986', NULL, 'https://www.google.com/maps?layer=c&cbll=27.091,77.6612&cbp=11,0,0,0,0', '/images/heritage/fatehpur-sikri.jpg', '1571', '2026-09-08', '2026-09-08'),
  (79, NULL, NULL, 'Konark Sun Temple', 'man-made', 'The 13th-century chariot-temple of the Sun, carved as a colossal stone wheel.', 'Built by Narasimhadeva I around 1250, the temple was conceived as Surya''s chariot drawn by seven horses; incredible carving remains despite the collapse of its superstructure.', 'Konark, Odisha', 19.8875, 86.0947, 'Eastern Ganga dynasty, 13th century', NULL, 'UNESCO World Heritage Site (1984), a summit of Kalingan architecture.', NULL, NULL, '/images/heritage/konark.jpg', 0, 'konark-sun-temple', 'tangible', 'Odisha', 'WORLD', '1984', 'Cultural', 'https://www.google.com/maps?layer=c&cbll=19.8875,86.0947&cbp=11,0,0,0,0', '/images/heritage/konark.jpg', 'c. 1250', '2026-09-08', '2026-09-08'),
  (80, NULL, NULL, 'Qutb Minar', 'man-made', 'The 72.5-metre victory tower of the Delhi Sultanate in the Qutb complex.', 'Started by Qutb-ud-din Aibak in 1192 (from c. 1198) and completed by Iltutmish, the tapering five-storey tower rises through bands of ornate Qur''anic calligraphy.', 'Delhi', 28.5245, 77.1855, 'Delhi Sultanate, 12th–13th century', NULL, 'UNESCO World Heritage Site (1993) — the tallest brick minaret in the world.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Qutb_minar_2015.jpg?width=900', 0, 'qutb-minar', 'tangible', 'Delhi', 'WORLD', '1993', NULL, 'https://www.google.com/maps?layer=c&cbll=28.5245,77.1855&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Qutb_minar_2015.jpg?width=900', '1198', '2026-09-08', '2026-09-08'),
  (81, NULL, NULL, 'Mysuru Palace', 'man-made', 'The royal seat of the Wodeyar dynasty, an Indo-Saracenic landmark famed for its Sunday illumination.', 'The present palace was rebuilt after a 1897 fire and completed in 1912, incorporating Hindu, Muslim, Rajput and Gothic motifs under the supervision of British architect Henry Irwin.', 'Mysuru, Karnataka', 12.3052, 76.655, 'Indo-Saracenic, 20th century', NULL, 'One of India''s most visited monuments and the stage for the ten-day Mysuru Dasara.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mysore_Palace,_Mysuru.jpg?width=900', 0, 'mysuru-palace', 'tangible', 'Mysuru, Karnataka', NULL, NULL, NULL, 'https://www.google.com/maps?layer=c&cbll=12.3052,76.655&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mysore_Palace,_Mysuru.jpg?width=900', '1912', '2026-09-08', '2026-09-08'),
  (82, NULL, NULL, 'Chittorgarh Fort', 'man-made', 'The largest fort of India, hilltop seat of the Sisodia Rajputs and legend of Padmini.', 'Older legend connects the fort to Mori Rajputs; the Sisodias ruled from here, surviving the great sieges of 1303, 1535 and 1567 that made Chittor synonymous with self-sacrifice (jauhar).', 'Chittorgarh, Rajasthan', 24.8864, 74.6457, 'Rajput, 7th century onward', NULL, 'Part of the UNESCO Hill Forts of Rajasthan (2013).', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chittorgarh_Fort,_Rajasthan.jpg?width=900', 0, 'chittorgarh-fort', 'tangible', 'Chittorgarh, Rajasthan', 'WORLD', '2013', NULL, 'https://www.google.com/maps?layer=c&cbll=24.8864,74.6457&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chittorgarh_Fort,_Rajasthan.jpg?width=900', '7th century', '2026-09-08', '2026-09-08'),
  (83, NULL, NULL, 'Hawa Mahal', 'man-made', 'The five-storey ''Palace of Winds'' with 953 latticed windows of pink sandstone.', 'Built by Maharaja Sawai Pratap Singh in 1799 as a screen for the royal women to observe street processions unseen.', 'Jaipur, Rajasthan', 26.9239, 75.8267, 'Rajput, 18th century', NULL, 'The architectural signature of the Pink City, Jaipur.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hawa_Mahal_view_from_the_street.jpg?width=900', 0, 'hawa-mahal', 'tangible', 'Jaipur, Rajasthan', NULL, NULL, NULL, 'https://www.google.com/maps?layer=c&cbll=26.9239,75.8267&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hawa_Mahal_view_from_the_street.jpg?width=900', '1799', '2026-09-08', '2026-09-08'),
  (84, NULL, NULL, 'Meenakshi Amman Temple', 'man-made', 'The great Dravidian temple of goddess Meenakshi and Sundareswarar, crowned by 14 gopurams.', 'Mentioned in ancient Sangam texts, the temple reached its present form under the Nayak rulers in the 16th–17th century; its thousand-pillared hall and sacred tank draw pilgrims year-round.', 'Madurai, Tamil Nadu', 9.9197, 78.1193, 'Pandya–Nayak, 16th–17th century rebuild', NULL, 'A living temple-town and a masterpiece of Dravidian gateway architecture.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Meenakshi_Amman_Temple,_Madurai.jpg?width=900', 0, 'meenakshi-temple', 'tangible', 'Madurai, Tamil Nadu', 'NOMINATED', NULL, 'Cultural', 'https://www.google.com/maps?layer=c&cbll=9.9197,78.1193&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Meenakshi_Amman_Temple,_Madurai.jpg?width=900', '16th century', '2026-09-08', '2026-09-08'),
  (85, NULL, NULL, 'Sanchi Stupa', 'man-made', 'The great Ashokan stupa complex, keeper of the Buddhist relic heritage.', 'Commissioned by Emperor Ashoka in the 3rd century BCE and enlarged under the Shungas and Satavahanas, the Great Stupa at Sanchi preserves magnificent toranas (gateways).', 'Sanchi, Madhya Pradesh', 23.4794, 77.7395, 'Mauryan–Shunga, 3rd c. BCE–1st c. CE', NULL, 'UNESCO World Heritage Site (1989).', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sanchi_Stupa_2.jpg?width=900', 0, 'sanchi-stupa', 'tangible', 'Sanchi, Madhya Pradesh', 'WORLD', '1989', NULL, 'https://www.google.com/maps?layer=c&cbll=23.4794,77.7395&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sanchi_Stupa_2.jpg?width=900', '3rd century BCE', '2026-09-08', '2026-09-08'),
  (86, NULL, NULL, 'Brihadeeswara Temple', 'man-made', 'The great Chola temple of Shiva, summit of South Indian architecture.', 'Built by Raja Raja Chola I and completed in 1010 CE, the 66-metre vimana rises without binding mortar and carries an 80-tonne capstone.', 'Thanjavur, Tamil Nadu', 10.783, 79.134, 'Chola, 11th century', NULL, 'UNESCO World Heritage Site — part of the Great Living Chola Temples (1987).', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brihadeeswara_Temple,_Thanjavur.jpg?width=900', 0, 'brihadeeswara-temple', 'tangible', 'Thanjavur, Tamil Nadu', 'WORLD', '1987', NULL, 'https://www.google.com/maps?layer=c&cbll=10.783,79.134&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brihadeeswara_Temple,_Thanjavur.jpg?width=900', '1010', '2026-09-08', '2026-09-08'),
  (87, NULL, NULL, 'Kaziranga National Park', 'natural', 'A riverine grassland sanctuary famed for the world''s largest population of the one-horned rhinoceros.', 'Declared a reserve in 1905 to save the Indian rhinoceros and a national park in 1974, Kaziranga''s flood-fed alluvial plains host tigers, elephants and rare swamp deer.', 'Assam', 26.5775, 93.1711, 'Est. 1905 (reserve); national park 1974', NULL, 'UNESCO World Heritage Site (1985) — a stronghold of the greater one-horned rhino.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Greater_One-Horned_Rhino_at_Kaziranga.jpg?width=900', 0, 'kaziranga', 'tangible', 'Assam', 'WORLD', '1985', NULL, 'https://www.google.com/maps?layer=c&cbll=26.5775,93.1711&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaziranga_National_Park_in_Assam,_India.jpg?width=900', '1974', '2026-09-08', '2026-09-08'),
  (88, NULL, NULL, 'Sundarbans National Park', 'natural', 'The world''s largest mangrove forest and the domain of the Royal Bengal tiger.', 'The tide-fed delta of the Ganga–Brahmaputra formed the Sundarbans mangroves over millennia; India''s national park was established in 1984 to protect the tigers that swim between the creeks.', 'West Bengal / Bangladesh delta', 21.9497, 89.1833, 'National park 1984', NULL, 'UNESCO World Heritage Site (1987), also inscribed as part of a transboundary property.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sundarbans_River.jpg?width=900', 0, 'sundarbans', 'tangible', 'West Bengal', 'WORLD', '1987', NULL, 'https://www.google.com/maps?layer=c&cbll=21.9497,88.9386&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sundarban_Tiger.jpg?width=900', '1984', '2026-09-08', '2026-09-08'),
  (89, NULL, NULL, 'Keoladeo National Park', 'natural', 'A man-made wetland refuge that hosts thousands of wintering Siberian cranes and waterfowl.', 'Originating as a duck-shooting reserve of the Bharatpur maharajas and named for the Keoladeo Shiva temple, the park supports over 370 bird species.', 'Bharatpur, Rajasthan', 27.1593, 77.5233, 'Wetland habitat (declared park 1981)', NULL, 'UNESCO World Heritage Site (1985).', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keoladeo_National_Park_birds.jpg?width=900', 0, 'keoladeo', 'tangible', 'Bharatpur, Rajasthan', 'WORLD', '1985', NULL, 'https://www.google.com/maps?layer=c&cbll=27.1592,77.5215&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Keoladeo_National_Park.jpg?width=900', '1981', '2026-09-08', '2026-09-08'),
  (90, NULL, NULL, 'Western Ghats', 'natural', 'An ancient mountain range older than the Himalayas, recognised as a biodiversity hotspot.', 'Running parallel to the western coast, the Ghats shelter thousands of endemic species and 39 nominated serial property components of rainforest, shola and grassland.', 'Kerala · Karnataka · Tamil Nadu · Maharashtra · Goa · Gujarat', 10.94, 76.95, 'Geological antiquity, mountainous uplift', NULL, 'UNESCO World Heritage Site (2012), one of the eight ''hottest'' biodiversity hotspots on Earth.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Western_Ghats_rainforest.jpg?width=900', 0, 'western-ghats', 'tangible', 'Kerala–Karnataka–Tamil Nadu–Maharashtra', 'WORLD', '2012', NULL, 'https://www.google.com/maps?layer=c&cbll=10.1697,77.0611&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Western_Ghats,_Chikmagalur.jpg?width=900', '—', '2026-09-08', '2026-09-08'),
  (91, NULL, NULL, 'Great Himalayan National Park', 'natural', 'A high-altitude sanctuary of deodar and alpine meadows along the Great Himalayan divide.', 'The park protects the catchment of the Jiwa Nal and Sainj rivers and harbours endangered species such as the snow leopard and musk deer.', 'Kullu, Himachal Pradesh', 31.833, 77.5, 'National park 1999', NULL, 'UNESCO World Heritage Site (2014).', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Great_Himalayan_National_Park_Kullu.jpg?width=900', 0, 'great-himalayan', 'tangible', 'Kullu, Himachal Pradesh', 'WORLD', '2014', NULL, 'https://www.google.com/maps?layer=c&cbll=31.8115,77.3531&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Great_Himalayan_National_Park.jpg?width=900', '1984', '2026-09-08', '2026-09-08'),
  (92, NULL, NULL, 'Nanda Devi & Valley of Flowers', 'natural', 'Twin Himalayan jewels: the sacred Nanda Devi basin and the alpine Valley of Flowers.', 'The Nanda Devi sanctuary was established in 1982; the Valley of Flowers, carpeted by endemic alpine flora in bloom, was added as an extension to the World Heritage property in 2005.', 'Chamoli, Uttarakhand', 30.3878, 79.9681, 'National parks est. 1982/1980', NULL, 'UNESCO World Heritage Site (1988, extended 2005).', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Valley_of_Flowers_2013_img05.jpg?width=900', 0, 'nanda-devi', 'tangible', 'Chamoli, Uttarakhand', 'WORLD', '1988', NULL, 'https://www.google.com/maps?layer=c&cbll=30.7283,79.6052&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Valley_of_Flowers_2.jpg?width=900', '1982', '2026-09-08', '2026-09-08'),
  (93, NULL, NULL, 'Ranthambore National Park', 'natural', 'A dry-deciduous tiger reserve crowned by the Ranthambore hill fort.', 'The former hunting grounds of the Jaipur maharajas became a sanctuary in 1955 and a Project Tiger reserve in 1973, now world-famous for its inquisitive tigers beside ruined temples.', 'Sawai Madhopur, Rajasthan', 26.0174, 76.5026, 'Sanctuary 1955; Project Tiger 1973', NULL, '[demo] Representative natural heritage entry.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ranthambore_tiger_Pugmark_0912.jpg?width=900', 0, 'ranthambore', 'tangible', 'Sawai Madhopur, Rajasthan', NULL, NULL, NULL, 'https://www.google.com/maps?layer=c&cbll=26.0173,76.5026&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ranthambore_tiger.jpg?width=900', '1973', '2026-09-08', '2026-09-08'),
  (94, NULL, NULL, 'Jim Corbett National Park', 'natural', 'India''s oldest national park, the first Project Tiger reserve, set along the Ramganga.', 'Established as Hailey National Park in 1936 on the sal forests of the Kumaon hills and renamed after naturalist Jim Corbett, it is home to the Bengal tiger, elephant and hornbill.', 'Nainital, Uttarakhand', 29.54, 78.935, 'National park 1936', NULL, '[demo] Representative natural heritage entry.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiger_in_Corbett.jpg?width=900', 0, 'jim-corbett', 'tangible', 'Nainital, Uttarakhand', NULL, NULL, NULL, 'https://www.google.com/maps?layer=c&cbll=29.5302,78.7747&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jim_Corbett_National_Park.jpg?width=900', '1936', '2026-09-08', '2026-09-08'),
  (95, NULL, NULL, 'Chilika Lake', 'natural', 'Asia''s largest brackish water lagoon, winter home to thousands of migratory birds.', 'The brackish lagoon of the Odisha coast shelters Irrawaddy dolphins and hosts over a million birds between October and March; it is a Ramsar wetland.', 'Puri–Khordha, Odisha', 19.7167, 85.3167, 'Wetland ecosystem', NULL, '[demo] Representative natural heritage entry.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chilika_lake_2020.jpg?width=900', 0, 'chilika', 'tangible', 'Odisha', NULL, NULL, NULL, 'https://www.google.com/maps?layer=c&cbll=19.7185,85.3227&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chilika_lake.jpg?width=900', '1981', '2026-09-08', '2026-09-08'),
  (96, NULL, NULL, 'Living Root Bridges of Meghalaya', 'natural', 'Living bridges grown by the Khasi people by guiding aerial roots of the rubber fig across rivers.', 'Trained over decades by the matrilineal Khasi communities of the rain-soaked hills, the ficus-elasticas bridges strengthen as they grow and can span up to 50 metres.', 'Khasi Hills, Meghalaya', 25.318, 91.7051, 'Traditional living structure (age varies)', NULL, '[demo] Representative natural heritage entry.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Double_Decker_Living_Root_Bridge,_Nongriat.jpg?width=900', 0, 'living-root-bridges', 'tangible', 'Meghalaya', 'TENTATIVE', '2022', 'Cultural', 'https://www.google.com/maps?layer=c&cbll=25.2548,91.7248&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Living_Root_Bridge.jpg?width=900', 'Centuries old', '2026-09-08', '2026-09-08'),
  (97, NULL, NULL, 'Khangchendzonga National Park', 'mixed', 'The only trans-Himalayan World Heritage site surrounds the world''s third-highest peak.', 'The park drapes the slopes of Mount Khangchendzonga (8,586 m) and is sacred to the Lepchas, who call it the ''treasure abode''; monasteries, dzongs and dramatic glacier valleys define the landscape.', 'Sikkim', 27.69, 88.2, 'National park 1977', NULL, 'India''s first and only ''Mixed'' UNESCO World Heritage Site (2016).', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kangchenjunga_from_Goechela_Pass.jpg?width=900', 0, 'khangchendzonga', 'tangible', 'Sikkim', 'WORLD', '2016', NULL, 'https://www.google.com/maps?layer=c&cbll=27.7232,88.1461&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Khangchendzonga_National_Park.JPG?width=900', '1977', '2026-09-08', '2026-09-08'),
  (98, NULL, NULL, 'Rock Shelters of Bhimbetka', 'mixed', 'Prehistoric rock art in natural cave galleries above the Vindhya range.', 'The shelters preserve some of South Asia''s earliest known human paintings, deposited over a staggering span from the Acheulian period to the medieval era.', 'Raisen, Madhya Pradesh', 22.9397, 77.6173, 'Acheulian–historical, up to 100,000 years', NULL, 'UNESCO World Heritage Site (2003) — art in a living natural setting.', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhimbetka_rock_paintings.jpg?width=900', 0, 'bhimbetka-rock-shelters', 'tangible', 'Raisen, Madhya Pradesh', 'WORLD', '2003', 'Cultural', 'https://www.google.com/maps?layer=c&cbll=22.9397,77.6173&cbp=11,0,0,0,0', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhimbetka_rock_paintings.jpg?width=900', 'Pleistocene–Holocene', '2026-09-08', '2026-09-08'),
  (99, NULL, NULL, 'Bharatanatyam', 'classical-dance', 'The oldest codified classical dance of India, sculpturally tied to the temples of Tamil Nadu.', '[demo] Practised in the temples and courts of the South for centuries, Bharatanatyam was systemised through the Natya Shastra and carried to the world stage by the devadasi-turned-guru generation of the early 20th century.', 'Tamil Nadu', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/images/heritage/dance-bharatanatyam.jpg', 0, 'bharatanatyam', 'intangible', 'Tamil Nadu', NULL, NULL, NULL, NULL, '/images/heritage/dance-bharatanatyam.jpg', NULL, '2026-09-08', '2026-09-08'),
  (100, NULL, NULL, 'Kathak', 'classical-dance', 'A classical dance of storytelling that fused Hindu temple narrative with the Mughal court.', '[demo] The kathakas (storytellers) of North India turned into the courtly dance of Lucknow, Jaipur and Benares gharanas, famed for chakkars (spins) and intricate footwork.', 'North India (Uttar Pradesh & Rajasthan)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kathak_dancer.jpg?width=900', 0, 'kathak', 'intangible', 'North India', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kathak_performance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (101, NULL, NULL, 'Odissi', 'classical-dance', 'The lyrical dance of the Jagannath temple, sculpted after the postures of Odishan temple art.', '[demo] Reconstructed in the 20th century from the mahari tradition and the Odra-Magadhi style, Odissi is recognisable by its tribhangi posture and hip-swaying movements.', 'Odisha', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Odissi_dance.jpg?width=900', 0, 'odissi', 'intangible', 'Odisha', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Odissi_dance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (102, NULL, NULL, 'Kathakali', 'classical-dance', 'The masked dance-drama of Kerala, sung and drummed into life with elaborate green-room makeup.', '[demo] Evolving from 17th-century Krishnanattam, Kathakali uses over 100 mudras, towering headgear and the percussive chenda to narrate epics across a single night.', 'Kerala', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kathakali_of_Kerala.jpg?width=900', 0, 'kathakali', 'intangible', 'Kerala', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kathakali_of_Kerala.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (103, NULL, NULL, 'Kuchipudi', 'classical-dance', 'A soulful dance-drama that balances lyricism with acrobatic talent from the Kuchipudi village.', '[demo] Rooted in the Bhama Kalapam of Siddhendra Yogi, Kuchipudi performers often dance on the rim of a brass plate and balance a pot of water.', 'Andhra Pradesh', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kuchipudi_performance.jpg?width=900', 0, 'kuchipudi', 'intangible', 'Andhra Pradesh / Telangana', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kuchipudi_dancer.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (104, NULL, NULL, 'Manipuri', 'classical-dance', 'The devotional Ras Lila dance of the Manipur Vaishnavas, set to the pung and the flute.', '[demo] Born of the temple traditions of Lord Krishna, Manipuri is known for its circular, unhurried grace and the bell-clad Jagoi style.', 'Manipur', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manipuri_dance.jpg?width=900', 0, 'manipuri', 'intangible', 'Manipur', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manipuri_dance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (105, NULL, NULL, 'Bhangra & Giddha', 'folk-dance', 'The harvest dances of Punjab — the vigorous men''s Bhangra and the repartee-filled women''s Giddha.', '[demo] Performed at Baisakhi and weddings to the dhol, Bhangra''s bouncing shoulder movements defined generations of celebratory dance.', 'Punjab', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhangra_Group.jpg?width=900', 0, 'bhangra-giddha', 'intangible', 'Punjab', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhangra_performance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (106, NULL, NULL, 'Garba & Dandiya Raas', 'folk-dance', 'The clapping circle dance of Navratri, accompanied by the dandiya sticks of Raas.', '[demo] Danced in concentric circles around the lamp (garba) of the goddess during the nine nights of Navratri across Gujarat.', 'Gujarat', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/images/trending/garba.jpg', 0, 'garba-dandiya', 'intangible', 'Gujarat', NULL, NULL, NULL, NULL, '/images/trending/garba.jpg', NULL, '2026-09-08', '2026-09-08'),
  (107, NULL, NULL, 'Kalbelia', 'folk-dance', 'The serpent-like dance of the Kalbelia snake-charmer community of Rajasthan.', 'Recognised by UNESCO as Intangible Cultural Heritage (2010); the twirling black-veiled dance is accompanied by the poongi and sarangi.', 'Rajasthan', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalbeliya_dance.jpg?width=900', 0, 'kalbelia', 'intangible', 'Rajasthan', 'INTANGIBLE', '2010', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalbelia_dance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (108, NULL, NULL, 'Chhau', 'folk-dance', 'A masked martial dance-drama performed at the Chaitra festival in the Chhau belt.', 'Recognised by UNESCO as Intangible Cultural Heritage (2010); instruments of dhol, mahuri and shepherd-horn drive the stylised hunt and war tales.', 'Eastern India (Jharkhand, West Bengal, Odisha)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chhau_dance.jpg?width=900', 0, 'chhau', 'intangible', 'Eastern India (Jharkhand, West Bengal, Odisha)', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chhau_dance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (109, NULL, NULL, 'Hindustani Classical Music', 'classical-music', 'The raga-based classical music of North India, spanning dhrupad, khayal and thumri.', '[demo] Carried through gharana lineages from the Muslim courts and the kirtan traditions, Hindustani music centres on improvisation within raga and tala.', 'North India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sitar_-_An_Introduction.jpg?width=900', 0, 'hindustani-classical', 'intangible', 'North India', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sitar_-_An_Introduction.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (110, NULL, NULL, 'Carnatic Music', 'classical-music', 'The devotional, composition-rich classical music of the South, from the Trinity''s kritis.', '[demo] Tyagaraja, Muthuswami Dikshitar and Shyama Sastri crystallised the Carnatic kriti repertoire in the 18th–19th centuries.', 'South India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Carnatic_ensemble.jpg?width=900', 0, 'carnatic-music', 'intangible', 'South India', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Carnatic_ensemble.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (111, NULL, NULL, 'Baul Music', 'folk-music', 'The ecstatic mystic music of the Bauls of Bengal, sung with ektara and duggi.', 'Recognised by UNESCO as Intangible Cultural Heritage (2008); the wandering Baul singers express a philosophy of inner search through song.', 'West Bengal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baul_performer.jpg?width=900', 0, 'baul-music', 'intangible', 'West Bengal', 'INTANGIBLE', '2008', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baul_performance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (112, NULL, NULL, 'Lavani', 'folk-songs', 'The powerful folk songs and dance of Maharashtra, once of the Peshwa courts.', '[demo] Combining bold lyrics, the dholki beat and the ghungroo, Lavani became the musical voice of Marathi theatre and folk stage.', 'Maharashtra', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lavani_dance.jpg?width=900', 0, 'lavani', 'intangible', 'Maharashtra', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lavani_dance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (113, NULL, NULL, 'Kutiyattam Sanskrit Theatre', 'theatre', 'The ancient Sanskrit theatre preserved in Kerala''s koothambalam temples.', 'Recognised by UNESCO as Intangible Cultural Heritage (2008); Kutiyattam is the only surviving Sanskrit drama tradition, with performers trained in niravanam acting through mudra and eye.', 'Kerala', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kutiyattam_performers.jpg?width=900', 0, 'kutiyattam', 'intangible', 'Kerala', 'INTANGIBLE', '2008', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kutiyattam_performance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (114, NULL, NULL, 'Ramlila', 'theatre', 'The traditional dramatic re-enactment of the Ramayana, culminating in Dussehra.', '[demo] Performed across North India on stage-epics lasting from days to a month; the Ramnagar (Varanasi) and Delhi Ramlilas are among the most elaborate.', 'North India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ramlila_Ramleela_stage.jpg?width=900', 0, 'ramlila', 'intangible', 'Uttar Pradesh & beyond', 'INTANGIBLE', '2008', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ramlila,_Ram_nagar.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (115, NULL, NULL, 'Chhau (masked dance-drama)', 'traditional-performing-arts', 'The martial mask-dance of the Chhau belt — see Folk Dance for the UNESCO description.', '[demo] Performed to war drums with masks of heroes, demons and animals during the spring Chaitra parva.', 'Eastern India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chhau_mask_dance.jpg?width=900', 0, 'chhau-performing-arts', 'intangible', 'Eastern India', 'INTANGIBLE', '2010', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chhau_mask_dance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (116, NULL, NULL, 'Puppetry', 'traditional-performing-arts', 'India''s traditional glove, string, rod and shadow puppetry traditions.', '[demo] From the tholu bommalata leather puppets of Andhra to the string puppets of Rajasthan and the glove puppets of Kerala, shadow play animated Indian epics for rural audiences.', 'Pan-India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tholu_Bommalata_shadow_puppets.jpg?width=900', 0, 'puppetry', 'intangible', 'India', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puppetry_India.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (117, NULL, NULL, 'Kalaripayattu', 'traditional-performing-arts', 'The ancient martial art of Kerala, considered among the oldest surviving combat systems.', '[demo] Practised in the kalari with the master (asan) teaching weapon and bare-hand sequences that share lineage with the yoga and ayurvedic body disciplines.', 'Kerala', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalaripayattu_training.jpg?width=900', 0, 'kalaripayattu', 'intangible', 'Kerala', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalaripayattu.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (118, NULL, NULL, 'Blue Pottery of Jaipur', 'traditional-crafts', 'The glazed quartz-and-multani-mitti pottery of Jaipur with Persian-Turkish ancestry.', '[demo] Famed for cobalt-blue decoration on an opaquely glazed body, the craft is fired at low temperature and painted freehand.', 'Rajasthan', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jaipur_Blue_Pottery.jpg?width=900', 0, 'blue-pottery', 'intangible', 'Jaipur, Rajasthan', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Blue_Pottery_Jaipur.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (119, NULL, NULL, 'Bidriware', 'traditional-crafts', 'The silver-inlaid black metalware of Bidar, invented in the 14th-century Bahmani court.', '[demo] Zinc alloy oxidised black carries engraved and inlaid silver arabesques; each piece is finished by scrubbing with earth from the Bidar fort moat.', 'Karnataka', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bidri_ware_vase.jpg?width=900', 0, 'bidriware', 'intangible', 'Bidar, Karnataka', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bidriware.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (120, NULL, NULL, 'Kondapalli Toys', 'handicrafts', 'The fat, lacquered wooden toys of Kondapalli village, mostly depictions of village life and mythology.', '[demo] Carved from soft poniki wood on a lathe and painted, the toys received a Geographical Indication tag in 2002.', 'Andhra Pradesh', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kondapalli_toys_1.jpg?width=900', 0, 'kondapalli-toys', 'intangible', 'Andhra Pradesh', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kondapalli_toys.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (121, NULL, NULL, 'Dokra (Dhokra) Metal Craft', 'handicrafts', 'The lost-wax (cire-perdue) metal casting practised by adivasi communities.', '[demo] Wax models are invested in clay and burnt out, leaving exquisite hollow bells, animals and deities of brass.', 'Odisha · West Bengal · Chhattisgarh', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dokra_craft_artifacts.jpg?width=900', 0, 'dokra-metal-craft', 'intangible', 'Odisha · West Bengal · Chhattisgarh', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dokra_craft_artifacts.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (122, NULL, NULL, 'Kanjeevaram Silk', 'textiles', 'The rich silk sarees of Kanchipuram, woven with contrast borders and zari.', '[demo] Woven in three silk and one zari shoots, Kanjeevarams are a heritage of the temple city, often inspired by temple motifs.', 'Tamil Nadu', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kanjeevaram_saree.jpg?width=900', 0, 'kanjeevaram', 'intangible', 'Tamil Nadu', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kanjeevaram_silk.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (123, NULL, NULL, 'Pashmina Weaving', 'textiles', 'The hand-spun, hand-woven shahtoosh of pashm goat wool with Sozni embroidery.', '[demo] Pashmina shawls of Kashmir, perfected through the 15th–19th centuries, earned the misnomer ''ring shawl'' for passing through a ring.', 'Jammu & Kashmir', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kashmiri_Pashmina_weaving.jpg?width=900', 0, 'pashmina', 'intangible', 'Kashmir', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pashmina_Shawls.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (124, NULL, NULL, 'Phulkari', 'textiles', 'The flower-embroidered shawls and odhnis of Punjab, stitched with a darning needle.', '[demo] The geometric flower-work of Phulkari is traditionally a women''s craft of the region, now revived across Punjab wedding trousseaux.', 'Punjab', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Phulkari_dupatta.jpg?width=900', 0, 'phulkari', 'intangible', 'Punjab', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Phulkari_embroidery.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (125, NULL, NULL, 'Madhubani Painting', 'traditional-artistic-forms', 'The ritual wall and floor painting of Mithila, laden with mythology and folk motifs.', '[demo] Traditionally done by women with fingers and natural dyes, Madhubani (Mithila) art records stories from the Ramayana and cosmic motifs.', 'Bihar', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Madhubani_painting_Mithila_art.jpg?width=900', 0, 'madhubani', 'intangible', 'Bihar', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Madhubani_Painting_(Bihar).jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (126, NULL, NULL, 'Pattachitra', 'traditional-artistic-forms', 'The scroll painting of Odisha, executed with painstaking borders on treated cloth.', '[demo] The ''patta'' scrolls of Puri narrate Jagannath mythology in outline-filled colour, accompanied by the singing of the dasa patara.', 'Odisha', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pattachitra_artist_painting.jpg?width=900', 0, 'pattachitra', 'intangible', 'Odisha', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pattachitra.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (127, NULL, NULL, 'Warli Painting', 'traditional-artistic-forms', 'The white-on-ochre ritual murals of the Warli tribe of the Sahyadri.', '[demo] Created for weddings and harvests using rice paste, the minimal geometric Warli figures depict people, trees, animals and the tarpa dance.', 'Maharashtra', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Warli_painting_designs.jpg?width=900', 0, 'warli', 'intangible', 'Maharashtra', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Warli_painting.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (128, NULL, NULL, 'Durga Puja', 'festivals-cultural-practices', 'The five-day worship of Goddess Durga that turns Kolkata into an open-air art gallery.', 'UNESCO added Durga Puja in Kolkata to the Representative List of the Intangible Cultural Heritage of Humanity in 2021.', 'West Bengal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Durga_puja_pandal_Kolkata.jpg?width=900', 0, 'durga-puja', 'intangible', 'West Bengal', 'INTANGIBLE', '2021', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Durga_Puja_at_Shobhabazar_Rajbari.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (129, NULL, NULL, 'Navratri & Dussehra', 'festivals-cultural-practices', 'The nine nights of the goddess and the triumph of Ram over Ravana.', '[demo] Celebrated as Durga Puja in the east, Navratri garba in the west, and Ramlila-Dussehra in the north, this is India''s most widespread festival cluster.', 'Pan-India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dandiya_dance.jpg?width=900', 0, 'navratri-dussehra', 'intangible', 'India', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dandiya_night.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (130, NULL, NULL, 'Onam', 'festivals-cultural-practices', 'The harvest festival of Kerala woven around the homecoming legend of King Mahabali.', '[demo] Celebrated with the pookalam flower carpet, the tiger-dance and the great snake-boat races.', 'Kerala', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Onam_pookalam.jpg?width=900', 0, 'onam', 'intangible', 'Kerala', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Onam_pookalam.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (131, NULL, NULL, 'Bihu', 'festivals-cultural-practices', 'The three-fold Assamese festival of spring, harvest and the New Year.', '[demo] Rongali Bihu in April marks seeding and the New Year with the flute, dhol and the Bihu dance.', 'Assam', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bihu_dance.jpg?width=900', 0, 'bihu', 'intangible', 'Assam', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bihu_dance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (132, NULL, NULL, 'Kumbh Mela', 'rituals-traditions', 'The great bathing festival that rotates among four sacred river cities.', 'Recognised by UNESCO as Intangible Cultural Heritage of Humanity (2017); argued as the largest peaceful gathering on Earth.', 'Prayagraj · Haridwar · Nashik · Ujjain', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kumbh_Mela_2013.jpg?width=900', 0, 'kumbh-mela', 'intangible', 'Prayagraj, Haridwar, Ujjain, Nashik', 'INTANGIBLE', '2017', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kumbh_Mela.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (133, NULL, NULL, 'Ganga Aarti at Varanasi', 'rituals-traditions', 'The evening fire offering to the Ganga on the ghats of Varanasi.', '[demo] Priests in saffron swing brass lamps to the rhythm of mantras and bells as thousands gather on the Dashashwamedh ghat.', 'Uttar Pradesh', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ganga_aarti_Varanasi.jpg?width=900', 0, 'ganga-aarti', 'intangible', 'Varanasi, Uttar Pradesh', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ganga_Aarti_Varanasi.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (134, NULL, NULL, 'Maram (Naga) Traditions', 'rituals-traditions', 'The weaving, song, log-drum and feast-of-merit traditions of the Naga tribes.', '[demo] Village head-hunting past gave way to elaborate festivals such as Hornbill; textiles and ritual dances remain markers of identity.', 'Nagaland', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Naga_tribe_dance.jpg?width=900', 0, 'naga-maram-traditions', 'intangible', 'Nagaland', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Naga_tribe_dance.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (135, NULL, NULL, 'Vedic Chanting', 'oral-traditions', 'The precise oral recitation of the Vedas, transmitted without change for millennia.', 'Recognised by UNESCO as Intangible Cultural Heritage (2008) for its exacting memorisation techniques including vikriti patha.', 'Pan-India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vedic_recitation.jpg?width=900', 0, 'vedic-chanting', 'intangible', 'India', 'INTANGIBLE', '2008', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vedic_chanting.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (136, NULL, NULL, 'Burrakatha', 'storytelling', 'The folk ballad of the Tellagolla bards, narrating epics to the thambura drum.', '[demo] A single narrator dances, sings and declaims over the burra (stuffed drum), cracking the whip on the audience''s conscience.', 'Andhra Pradesh & Telangana', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burrakatha_performance.jpg?width=900', 0, 'burrakatha', 'intangible', 'Andhra Pradesh / Telangana', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burrakatha.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (137, NULL, NULL, 'Pandavani', 'storytelling', 'The folk narration of the Mahabharata''s Pandava tales through song and gesture.', '[demo] Usually a solo woman narrator, wielding a cymbal and peacock-feather, dramatically enacts the Kurukshetra saga.', 'Chhattisgarh', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pandavani_singer.jpg?width=900', 0, 'pandavani', 'intangible', 'Chhattisgarh', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pandavani_performers.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (138, NULL, NULL, 'Yoga', 'traditional-knowledge', 'The mind-body discipline of asana, pranayama and meditation from the Indian Yogic tradition.', 'UNESCO inscribed ''Yoga'' on the Representative List of the Intangible Cultural Heritage of Humanity in 2016; 21 June is observed as International Day of Yoga.', 'Pan-India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yoga_group_class.jpg?width=900', 0, 'yoga', 'intangible', 'India', 'INTANGIBLE', '2016', 'Representative List of the ICH of Humanity', NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yoga_-_Surya_Namaskara.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
  (139, NULL, NULL, 'Traditional Medicine (Ayurveda & Sowa Rigpa)', 'traditional-knowledge', 'The evidence-and-heritage based healing systems of Ayurveda and Himalayan Sowa Rigpa.', '[demo] From the Ashtavaidya families of Kerala to the amchi doctors of Ladakh, traditional medicine is a living knowledge system under national regulation.', 'Pan-India', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ayurvedic_medicines.jpg?width=900', 0, 'traditional-medicine', 'intangible', 'India', NULL, NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ayurveda_medicine.jpg?width=900', NULL, '2026-09-08', '2026-09-08'),
