INSERT INTO "community_posts" ("id", "kind", "title", "content", "author_name", "status", "created_at", "related_resource", "related_city", "image_url", "supabase_user_id") VALUES
  (1, 'photo', 'Shaniwar Wada at dusk', 'The illuminated fountain court of the Peshwa palace is a sight to hold. The wada''s bastion shadows carry the old city''s dusk prayers.', 'Rohan Patil', 'APPROVED', '2026-08-05', 'Shaniwar Wada', 'Pune', '', NULL),
  (2, 'experience', 'A monsoon trek to Sinhagad', 'Clouds roll over the Khadakwasla side and the fort gates echo with the local legend of Tanaji''s last stand.', 'Meera Deshpande', 'APPROVED', '2026-08-20', 'Sinhagad Fort', 'Pune', '', NULL),
  (3, 'review', 'Raja Dinkar Kelkar Museum — a cabinet of wonders', 'The nut-crackers, palanquins and caste-lanthorns are proof that museums of everyday things teach the most.', 'Arjun Kulkarni', 'APPROVED', '2026-08-20', 'Raja Dinkar Kelkar Museum', 'Pune', '', NULL),
  (4, 'story', 'My grandmother''s Ganeshotsav', 'The wada-life of Shukravar peth — the modak steam rising with the evening aarti — is our real intangible heritage.', 'Sonali Joshi', 'APPROVED', '2026-08-20', NULL, 'Pune', '', NULL),
  (5, 'photo', 'Meenakshi gopuram stones', 'The 14 rainbow towers of Madurai photographed from the Pottramarai tank.', 'Karthik Rajan', 'APPROVED', '2026-08-20', 'Meenakshi Amman Temple', 'Madurai', '', NULL),
  (6, 'experience', 'Durga Puja pandal-hopping', 'Kolkata in October is an outdoor museum — every pandal an exhibition of last year''s craftsmanship.', 'Ananya Sen', 'APPROVED', '2026-08-20', NULL, 'Kolkata', '', NULL),
  (7, 'review', 'Sarnath Museum — the lion''s silence', 'The Ashokan capital speaks more quietly than any lecture hall. A must-walk for students.', 'Devansh Shukla', 'APPROVED', '2026-08-20', 'Sarnath', 'Varanasi', '', NULL),
  (8, 'Story', 'Living Heritage in Varanasi', 'Exploring ghats and morning rituals in ancient Kashi.', 'Aarav Sharma', 'PENDING', '2026-09-09', NULL, NULL, NULL, 'user-uuid-123');
